.02],[57.43,60.33],[61.15,70.58],[64.71,74.21],[69.04,75.87],[72.91,76.03],[77.09,74.88],[80.5,72.56],[82.66,69.75],[83.75,66.94],[83.9,63.47],[83.13,60.33],[81.42,57.36],[79.1,55.04],[69.97,50.41],[67.65,47.27],[66.87,43.31],[67.18,35.87],[68.89,29.75],[70.59,26.78],[76.47,21.16]]]}},"punto":[15.48,42.15],"pista":"Es la zona pálida que rodea a la mariposa.","exp":"Axones mielinizados que suben y bajan por la médula (los cordones)."},{"clave":"canal-central","nombre":"Canal central","zona":{"e":[[51.39,51.07,2.48,2.64]]},"punto":[51.39,51.07],"pista":"Es el pequeño orificio en el centro de la mariposa.","exp":"Resto del tubo neural, revestido por células ependimarias; tiene líquido cefalorraquídeo."},{"clave":"fisura-ventral","nombre":"Fisura media ventral","zona":{"r":[[47.37,71.9,8.36,23.97]]},"punto":[51.39,86.78],"pista":"Es la hendidura ancha del borde, en la línea media, abajo.","exp":"Marca el lado ventral: es más ancha y profunda que el tabique dorsal."},{"clave":"tabique-dorsal","nombre":"Tabique medio dorsal","zona":{"r":[[48.61,4.13,5.57,40.5]]},"punto":[51.39,14.05],"pista":"Es la línea delgada que baja desde el borde de arriba hasta la mariposa.","exp":"Divide en dos los cordones dorsales; marca el lado dorsal."}],"orden":[],"preguntas":[{"p":"¿Cómo reconoces el lado ventral de este corte?","ops":["Por la fisura media ventral y las astas anchas con somas grandes","Por el tabique medio dorsal y las astas delgadas sin somas grandes","Por el canal central, que siempre queda junto al borde ventral","Por la sustancia blanca, que sólo rodea a la médula por ese lado"],"ok":0,"pista":"Busca la hendidura del borde y el asta donde están las neuronas más grandes.","exp":"El lado ventral tiene la fisura media ventral (una hendidura profunda) y las astas ventrales, anchas, con las motoneuronas. El dorsal tiene un tabique delgado y astas dorsales angostas."},{"p":"Según tu orientación, ¿qué llega al asta dorsal y qué sale del asta ventral?","ops":["Llega información sensitiva por la raíz dorsal y salen órdenes motoras por la ventral","Llegan órdenes motoras por la raíz dorsal y sale información sensitiva por la ventral","Llega líquido cefalorraquídeo del canal y sale mielina hacia la sustancia blanca","Llegan axones del encéfalo por la raíz dorsal y salen hacia el encéfalo por la ventral"],"ok":0,"pista":"Dorsal = entrada sensitiva; ventral = salida motora.","exp":"Es la ley de Bell-Magendie: la raíz dorsal es sensitiva (entrada) y la ventral es motora (salida). Por eso el asta dorsal recibe y el asta ventral, con sus motoneuronas, envía."}]}]},{"n":2,"tipo":"rompecabezas","titulo":"Los extremos del arco","tablero":"img/reflejo/tablero-huecos.jpg","huecos":true,"instrucciones":"La médula ya está. Completa los huecos punteados: toca un hueco y elige su pieza, o arrastra la pieza a cualquier parte de su hueco. Primero el lado <strong>sensitivo</strong> (lo que trae la información) y después el <strong>motor</strong> (lo que la lleva al músculo). <strong>Verde</strong>: correcto. <strong>Rojo</strong>: por repasar. <strong>Naranjo</strong>: lo que estás haciendo.","grupos":{"sensitivo":"1. Lado sensitivo: receptores → nervio → ganglio → raíz dorsal","motor":"2. Lado motor: raíz ventral → nervio → músculo"},"piezas":[{"clave":"piel","nombre":"Piel","grupo":"sensitivo","img":"img/reflejo/piezas/piel.webp","caja":[1.76,8.5,25.65,21.97],"zona":{"p":[[[1.82,14.16],[1.89,28.22],[2.47,29.49],[19.53,30.27],[21.35,29.3],[24.54,29.3],[27.28,24.61],[27.28,10.74],[26.5,9.77],[22.33,9.77],[19.99,9.08],[16.02,9.77],[13.35,8.98],[10.29,9.38],[7.36,8.59],[5.99,9.38]]]},"pista":"El bloque de arriba, con sus capas.","exp":"Tiene receptores: las terminaciones libres de dolor y temperatura inician el reflejo de retirada."},{"clave":"musculo-extensor","nombre":"Músculo con huso (extensor)","grupo":"sensitivo","img":"img/reflejo/piezas/musculo-extensor.webp","caja":[1.17,39.55,36.59,21.48],"zona":{"p":[[[1.24,48.73],[1.37,50.29],[3.65,51.17],[8.14,56.25],[10.61,58.4],[13.54,59.96],[17.51,60.84],[21.35,60.74],[25.0,59.77],[27.34,58.5],[33.14,53.81],[36.33,53.03],[36.46,53.91],[37.63,53.12],[37.57,47.27],[35.87,47.95],[33.66,47.56],[28.26,43.16],[28.71,42.77],[27.41,41.89],[25.85,41.89],[22.59,40.43],[19.73,39.75],[16.28,39.65],[13.54,40.14],[9.9,41.6],[5.21,44.73],[3.45,45.12],[1.82,44.53],[1.63,45.61],[2.15,46.09],[1.5,46.58],[1.82,47.07],[1.3,47.85],[1.5,48.24]]]},"pista":"El músculo del medio: en su interior se ve el huso.","exp":"Su huso muscular detecta el estiramiento: es el receptor del reflejo rotuliano. Además es efector (se contrae)."},{"clave":"nervio","nombre":"Nervio espinal y sus ramos","grupo":"sensitivo","img":"img/reflejo/piezas/nervio.webp","caja":[16.93,23.73,41.73,40.23],"zona":{"p":[[[16.99,30.47],[21.22,30.96],[24.48,32.71],[26.11,34.96],[27.8,38.38],[29.62,40.53],[27.47,41.7],[28.84,42.68],[31.9,42.38],[39.39,45.21],[37.7,47.17],[37.7,53.03],[36.33,54.1],[35.42,57.71],[34.38,59.86],[31.38,62.89],[32.75,63.77],[34.51,62.3],[36.07,59.96],[37.3,56.74],[38.74,51.17],[40.76,47.95],[42.32,46.68],[43.82,46.09],[46.22,46.19],[47.92,46.78],[47.98,44.24],[47.53,43.85],[48.37,41.6],[50.65,38.57],[51.5,37.99],[55.34,38.38],[57.88,37.11],[55.47,37.79],[53.39,37.21],[51.82,35.84],[50.39,33.01],[48.57,35.94],[44.27,40.33],[41.02,41.5],[36.98,41.5],[33.46,40.43],[30.08,38.28],[28.12,35.64],[25.98,31.84],[24.09,30.08],[24.35,29.39],[21.35,29.39],[19.53,30.37]]]},"pista":"La vía que se ramifica hacia la piel y los músculos.","exp":"Une la raíz dorsal y la ventral: es mixto (sensitivo y motor). Sus ramos llegan a la piel y a los músculos."},{"clave":"ganglio","nombre":"Ganglio de la raíz dorsal","grupo":"sensitivo","img":"img/reflejo/piezas/ganglio.webp","caja":[50.39,23.73,10.55,14.16],"zona":{"p":[[[59.11,25.2],[57.23,23.83],[55.4,24.61],[53.45,26.37],[51.82,28.91],[50.46,32.71],[51.24,34.86],[53.06,36.91],[55.47,37.7],[57.55,37.11],[59.11,35.74],[60.48,32.91],[60.81,30.47],[60.48,28.03]]]},"pista":"El abultamiento entre el nervio y la médula, del lado de arriba.","exp":"Tiene los somas de las neuronas sensitivas (pseudounipolares) rodeados de células satélite."},{"clave":"raiz-dorsal","nombre":"Raíz dorsal","grupo":"sensitivo","img":"img/reflejo/piezas/raiz-dorsal.webp","caja":[58.53,21.29,10.22,10.06],"zona":{"p":[[[68.62,21.68],[66.15,21.48],[61.39,24.61],[60.42,24.61],[58.92,23.83],[58.59,23.93],[58.59,24.51],[60.16,26.86],[61.0,31.15],[62.37,28.42],[64.45,26.66]]]},"pista":"Une el ganglio con el lado dorsal de la médula.","exp":"Lleva la rama central de las sensitivas hasta el asta dorsal."},{"clave":"raiz-ventral","nombre":"Raíz ventral","grupo":"motor","img":"img/reflejo/piezas/raiz-ventral.webp","caja":[47.98,44.14,14.78,17.38],"zona":{"p":[[[48.05,44.34],[48.05,46.88],[49.22,47.85],[53.71,55.18],[56.12,57.32],[60.55,59.57],[62.04,61.33],[62.63,61.23],[60.87,56.74],[59.9,52.73],[59.83,54.59],[57.94,54.69],[56.38,54.0],[54.36,52.15],[50.65,46.09]]]},"pista":"Sale del lado ventral de la médula, el de las astas anchas.","exp":"Lleva los axones de las motoneuronas desde el asta ventral hacia el nervio."},{"clave":"musculo-flexor","nombre":"Músculo flexor","grupo":"motor","img":"img/reflejo/piezas/musculo-flexor.webp","caja":[1.95,62.79,43.88,27.73],"zona":{"p":[[[2.15,69.43],[2.15,70.7],[5.6,73.54],[9.96,80.27],[13.15,84.38],[17.06,87.79],[20.7,89.65],[24.02,90.33],[28.32,90.14],[38.8,86.43],[41.21,86.62],[44.47,87.79],[44.66,86.13],[45.05,85.55],[45.12,83.98],[45.44,83.59],[45.31,83.01],[45.7,82.62],[41.34,80.27],[35.09,70.51],[32.42,67.87],[30.21,66.41],[30.21,65.72],[32.68,63.87],[31.38,62.99],[27.99,65.43],[24.02,63.57],[20.12,62.89],[14.65,63.48],[7.75,66.6],[5.92,66.5],[3.52,65.33],[3.58,65.92],[3.12,66.31],[3.39,66.7],[2.86,67.19],[3.19,67.68],[2.41,68.36],[2.6,68.75]]]},"pista":"El músculo de abajo, al final del ramo que baja.","exp":"Efector del reflejo de retirada: al contraerse, aleja la extremidad del estímulo."}],"preguntas":[{"p":"¿Por qué la raíz dorsal tiene un ganglio y la ventral no?","ops":["Los somas sensitivos están fuera de la médula; los motores, dentro","La raíz dorsal es más larga y necesita un relevo en el camino","En el ganglio ocurre la sinapsis entre la sensitiva y la motora","La raíz ventral no lleva axones, sólo glía y vasos sanguíneos"],"ok":0,"pista":"¿Dónde están los somas de las motoneuronas? ¿Y los de las sensitivas?","exp":"El ganglio agrupa los somas de las neuronas sensitivas, fuera del SNC. Los somas motores están dentro, en el asta ventral, así que la raíz ventral sólo lleva axones. En el ganglio no hay sinapsis."},{"p":"El nervio espinal lleva juntos axones sensitivos y motores. ¿Cómo se clasifica?","ops":["Mixto: lleva fibras sensitivas y motoras a la vez","Sensitivo: sólo lleva información hacia la médula","Motor: sólo lleva las órdenes hacia los músculos","Autónomo: sólo controla las vísceras y glándulas"],"ok":0,"pista":"Recuerda qué raíces se unen para formarlo.","exp":"Todos los nervios espinales son mixtos: reciben fibras de la raíz dorsal (sensitivas) y de la ventral (motoras). Por eso una lesión del nervio afecta la sensibilidad y la fuerza a la vez."}]},{"n":3,"tipo":"circuito","titulo":"Reflejo rotuliano","fondo":"img/reflejo/esquema-base.jpg","vb":[1536,1024],"instrucciones":"Al golpear el tendón se estira el extensor. <strong>1. Ubica</strong> cada neurona tocando dónde está su soma (aparece al acertar). <strong>2. Conecta</strong> las dos vías tocando las neuronas en el orden en que viaja la información. <strong>3. Lupas</strong>: toca cada 🔍 y responde. <strong>4. Preguntas</strong>. <strong>Verde</strong>: correcto. <strong>Rojo</strong>: por repasar. <strong>Naranjo</strong>: lo que estás haciendo.","circuitos":[{"clave":"rotuliano","titulo":"Reflejo rotuliano","sub":"con inhibición recíproca","estimulo":"Golpe del martillo en el tendón bajo la rótula: el cuádriceps (extensor) se estira.","receptor":"Huso muscular","efector":"Extensor","piezas":[{"clave":"sensitiva","nombre":"Neurona sensitiva del huso","detalle":"pseudounipolar","icono":"Pseudounipolar","color":"#2563EB","zona":{"e":[[55.47,30.86,5.34,7.03]]},"zona_nombre":"Ganglio de la raíz dorsal","punto":[55.34,29.1],"pista":"Su soma está fuera de la médula, en el abultamiento de la raíz dorsal.","exp":"Su soma está en el ganglio de la raíz dorsal. La rama periférica trae la señal del receptor y la rama central entra a la médula por la raíz dorsal, sin sinapsis en el ganglio.","trazo":{"color":"#2563EB","ico":"Pseudounipolar","soma":[850,298,24],"d":["M292,500 C320,470 360,448 410,438 S560,432 610,440 S700,425 740,400 S810,345 850,338","M850,338 L850,322","M850,338 C880,315 920,285 960,268 S1040,238 1068,250 C1085,262 1092,285 1105,310 S1128,345 1132,370 C1136,420 1110,480 1080,512"],"fino":["M262,492 q8,-14 16,0 q8,14 16,0 q8,-14 16,0","M1133,395 C1145,420 1155,440 1160,458"],"botones":[[1080,512,7],[1069,509,6],[1088,519,6],[1160,462,6]],"lbl":[0,-36,"middle"]}},{"clave":"motora-ext","nombre":"Motoneurona del extensor","detalle":"multipolar","icono":"Motoneurona","color":"#DC2626","zona":{"p":[[[67.84,48.83],[66.67,50.78],[66.08,53.22],[66.34,56.45],[67.64,59.08],[69.34,60.45],[71.81,60.84],[73.83,59.96],[75.26,58.2],[77.21,51.86],[77.21,47.46],[69.4,47.46]]]},"zona_nombre":"Asta ventral","punto":[68.03,53.22],"pista":"Busca el asta ancha de la mariposa, la del lado de la raíz ventral.","exp":"Su soma está en el asta ventral y su axón sale por la raíz ventral y el nervio hasta la placa motora: es la vía final común. Inerva al extensor, el mismo músculo que se estiró.","trazo":{"color":"#DC2626","ico":"Motoneurona","soma":[1045,545,26],"d":["M1045,545 C1020,565 990,580 962,590 C905,572 855,530 800,494 S705,452 620,450 S500,438 470,440 C450,445 438,460 430,476"],"fino":[],"botones":[[424,484,6],[436,486,6],[430,492,6]],"lbl":[-36,-30,"end"]}},{"clave":"inhib","nombre":"Interneurona inhibitoria","detalle":"multipolar","icono":"Multipolar","color":"#7C3AED","zona":{"e":[[76.5,44.73,3.78,4.3]],"p":[]},"zona_nombre":"Sustancia gris intermedia","punto":[76.17,45.9],"pista":"Está en la sustancia gris, entre el asta dorsal y la ventral, cerca del canal central.","exp":"Recibe una colateral de la sensitiva y frena a la motoneurona del músculo antagonista.","trazo":{"color":"#7C3AED","ico":"Multipolar","soma":[1170,470,18],"d":["M1165,488 C1162,515 1155,540 1140,562"],"fino":[],"botones":[[1138,565,6],[1148,566,6]],"lbl":[28,-6,"start"]}},{"clave":"motora-flex","nombre":"Motoneurona del flexor","detalle":"multipolar","icono":"Motoneurona","color":"#EA580C","zona":{"p":[[[67.84,48.83],[66.67,50.78],[66.08,53.22],[66.34,56.45],[67.64,59.08],[69.34,60.45],[71.81,60.84],[73.83,59.96],[75.26,58.2],[77.21,51.86],[77.21,47.46],[69.4,47.46]]]},"zona_nombre":"Asta ventral","punto":[72.79,57.13],"pista":"Busca el asta ancha de la mariposa, la del lado de la raíz ventral.","exp":"Su soma está en el asta ventral y su axón sale por la raíz ventral y el nervio hasta la placa motora: es la vía final común. Inerva al flexor, el antagonista.","trazo":{"color":"#EA580C","ico":"Motoneurona","soma":[1118,585,22],"d":["M1118,585 L1100,590 C1050,600 1000,598 965,598 C905,582 855,542 800,504 S705,462 625,460 C600,480 590,520 575,580 S500,650 430,690"],"fino":["M430,690 C390,700 340,705 300,715 M430,690 C400,715 360,735 325,755 M430,690 C415,730 400,760 388,790 M430,690 C440,730 450,760 457,793"],"botones":[[300,715,6],[325,755,6],[388,790,6],[457,793,6]],"lbl":[0,50,"middle"]}}],"vias":[{"titulo":"Vía directa","orden":["sensitiva","motora-ext"],"pista":"Empieza por la neurona que recibe del huso; ¿con quién hace sinapsis directo?","exp":"Huso → sensitiva (ganglio, raíz dorsal) → motoneurona del extensor (asta ventral, raíz ventral) → el extensor se contrae: una sola sinapsis central.","ruta":"M292,500 C320,470 360,448 410,438 S560,432 610,440 S700,425 740,400 S810,345 850,338 C880,315 920,285 960,268 S1040,238 1068,250 C1085,262 1092,285 1105,310 S1128,345 1132,370 C1136,420 1110,480 1080,512 L1045,545 C1020,565 990,580 962,590 C905,572 855,530 800,494 S705,452 620,450 S500,438 470,440 C450,445 438,460 430,476"},{"titulo":"Inhibición recíproca","orden":["sensitiva","inhib","motora-flex"],"inhibe":"motora-flex","pista":"La colateral de la sensitiva pasa por una interneurona antes de llegar al flexor.","exp":"Sensitiva → interneurona inhibitoria → motoneurona del flexor, que queda frenada: el antagonista se relaja.","ruta":"M292,500 C320,470 360,448 410,438 S560,432 610,440 S700,425 740,400 S810,345 850,338 C880,315 920,285 960,268 S1040,238 1068,250 C1085,262 1092,285 1105,310 S1128,345 1132,370 L1133,395 C1145,420 1155,440 1160,458 L1170,470 L1165,488 C1162,515 1155,540 1140,562 L1118,585"}],"lupas":[{"clave":"huso","titulo":"Huso muscular","img":"img/reflejo/huso-muscular.jpg","x":262,"y":520,"preguntas":[{"p":"¿Qué estímulo activa a la terminación azul enrollada en el huso?","ops":["El estiramiento del músculo, que deforma las fibras intrafusales","La contracción voluntaria del músculo, que acorta las fibras","El dolor del golpe del martillo sobre la piel de la rodilla","La acetilcolina liberada por la motoneurona sobre el huso"],"ok":0,"pista":"Piensa en qué le hace el martillo al tendón y al músculo.","exp":"El golpe estira el tendón y el cuádriceps; el estiramiento deforma la terminación anuloespiral y abre canales iónicos: nace el potencial en la neurona sensitiva."},{"p":"¿En qué se diferencian las fibras del huso de las del resto del músculo?","ops":["Son intrafusales: detectan longitud y casi no aportan fuerza","Son extrafusales: generan casi toda la fuerza del músculo","Son nerviosas: forman parte del axón de la neurona sensitiva","Son tendinosas: unen el músculo con el hueso de la rótula"],"ok":0,"pista":"El huso está dentro de una cápsula.","exp":"Las fibras intrafusales están dentro de la cápsula del huso y funcionan como sensor de longitud; las extrafusales hacen la fuerza."}]},{"clave":"excitatoria","titulo":"Sinapsis excitatoria (azul → roja)","img":"img/reflejo/sinapsis-excitatoria.jpg","x":1098,"y":492,"preguntas":[{"p":"¿Qué neurotransmisor libera la sensitiva sobre la motoneurona?","ops":["Glutamato, que excita a la motoneurona","GABA, que inhibe a la motoneurona","Acetilcolina, que contrae al músculo","Glicina, que frena a la motoneurona"],"ok":0,"pista":"Es el principal neurotransmisor excitatorio del sistema nervioso central.","exp":"La sensitiva libera glutamato: abre canales de Na⁺ en la motoneurona, que se despolariza y dispara."},{"p":"En la lupa, ¿qué lado es presináptico y cuál postsináptico?","ops":["Presináptico: el botón azul con vesículas; postsináptico: la roja","Presináptico: la roja con receptores; postsináptico: el botón azul","Ambos son presinápticos, porque los dos liberan vesículas","Ninguno: la hendidura es una unión directa entre citoplasmas"],"ok":0,"pista":"Las vesículas están en la neurona que envía.","exp":"El botón de la sensitiva (azul) tiene las vesículas y libera; la motoneurona (roja) tiene los receptores. Entre ambos queda la hendidura sináptica."}]},{"clave":"inhibitoria","titulo":"Sinapsis inhibitoria (morada → naranja)","img":"img/reflejo/sinapsis-inhibitoria.jpg","x":1178,"y":575,"preguntas":[{"p":"¿Qué hace la interneurona morada sobre la motoneurona naranja?","ops":["La inhibe con glicina o GABA y el flexor se relaja","La excita con glutamato y el flexor se contrae","La inhibe con acetilcolina y el extensor se relaja","La excita con glicina y el extensor se contrae"],"ok":0,"pista":"Mira el color de la lupa: es la sinapsis inhibitoria.","exp":"La interneurona inhibitoria libera glicina (o GABA), abre canales de Cl⁻ e hiperpolariza a la motoneurona del flexor: el músculo antagonista se relaja."},{"p":"¿Para qué sirve frenar al flexor mientras se contrae el extensor?","ops":["Para que el antagonista no se oponga y la pierna se extienda","Para que el flexor descanse y se recupere del golpe del martillo","Para que la señal suba al encéfalo antes de contraer el extensor","Para que el huso del flexor deje de estirarse y se apague"],"ok":0,"pista":"Si los dos músculos se contrajeran a la vez, ¿se movería la rodilla?","exp":"Es la inhibición recíproca: mientras el agonista se contrae, el antagonista se relaja y el movimiento es eficiente."}]},{"clave":"placa","titulo":"Placa motora","img":"img/reflejo/placa-motora.jpg","x":470,"y":500,"preguntas":[{"p":"¿Qué neurotransmisor libera la motoneurona en la placa motora?","ops":["Acetilcolina, que abre canales en la fibra muscular","Glutamato, que abre canales en la fibra muscular","Glicina, que relaja la fibra muscular al instante","Noradrenalina, que acelera la fibra muscular"],"ok":0,"pista":"Es el mismo neurotransmisor de todas las uniones neuromusculares del músculo esquelético.","exp":"La acetilcolina se une a receptores nicotínicos de la fibra muscular, la despolariza y desencadena la contracción."},{"p":"¿Para qué sirven los pliegues de la membrana muscular bajo el botón?","ops":["Aumentan la superficie con receptores de acetilcolina","Guardan las vesículas de acetilcolina de la motoneurona","Aíslan la fibra para que el impulso no se escape","Producen la mielina que envuelve al axón motor"],"ok":0,"pista":"Fíjate qué hay en la membrana de los pliegues.","exp":"Los pliegues de la unión neuromuscular multiplican la superficie con receptores: cada impulso libera acetilcolina suficiente para contraer la fibra."}]}],"preguntas":[{"p":"¿Cómo se clasifica el reflejo rotuliano?","ops":["Monosináptico: una sola sinapsis central, sin interneurona","Polisináptico: varias sinapsis centrales, con interneuronas","Monosináptico: una sola neurona, que es sensitiva y motora","Polisináptico: varias sinapsis dentro del ganglio dorsal"],"ok":0,"pista":"Cuenta las sinapsis entre la sensitiva y la motoneurona.","exp":"Es monosináptico: es el reflejo más rápido. Por eso se usa para evaluar el arco reflejo (nervio, raíz, segmento medular y músculo)."},{"p":"Si la vía directa es monosináptica, ¿por qué hay una interneurona en este reflejo?","ops":["Frena al antagonista: es otra vía, en paralelo a la directa","Retrasa la contracción del extensor para que sea más suave","Lleva la información del huso hacia el encéfalo para sentirla","Reemplaza a la motoneurona cuando el golpe es muy fuerte"],"ok":0,"pista":"Mira hacia qué motoneurona va la morada.","exp":"La vía directa (sensitiva → motoneurona del extensor) tiene una sola sinapsis. La interneurona está en una vía paralela que inhibe al flexor."}]}]},{"n":4,"tipo":"circuito","titulo":"Reflejo de retirada","fondo":"img/reflejo/esquema-base.jpg","vb":[1536,1024],"instrucciones":"Pisas un clavo. Las dos motoneuronas ya están. <strong>1. Ubica</strong> la sensitiva y las dos interneuronas. <strong>2. Conecta</strong> las dos vías. <strong>3. Lupas</strong>. <strong>4. Preguntas</strong>. <strong>Verde</strong>: correcto. <strong>Rojo</strong>: por repasar. <strong>Naranjo</strong>: lo que estás haciendo.","circuitos":[{"clave":"retirada","titulo":"Reflejo de retirada","sub":"polisináptico","estimulo":"Pisas un clavo: el pie se retira antes de que sientas el dolor.","receptor":"Nociceptor (piel)","efector":"Flexor","piezas":[{"clave":"sensitiva","nombre":"Neurona sensitiva del dolor","detalle":"pseudounipolar","icono":"Pseudounipolar","color":"#0891B2","zona":{"e":[[55.47,30.86,5.34,7.03]]},"zona_nombre":"Ganglio de la raíz dorsal","punto":[55.34,29.1],"pista":"Su soma está fuera de la médula, en el abultamiento de la raíz dorsal.","exp":"Su soma está en el ganglio de la raíz dorsal. La rama periférica trae la señal del receptor y la rama central entra a la médula por la raíz dorsal, sin sinapsis en el ganglio. Sus terminaciones libres en la piel son nociceptores.","trazo":{"color":"#0891B2","ico":"Pseudounipolar","soma":[850,298,24],"d":["M228,285 C280,300 340,305 375,325 S430,395 470,418 S570,430 610,438 S700,420 740,395 S810,345 850,338","M850,338 L850,322","M850,338 C880,315 920,285 960,268 S1040,238 1068,250 C1085,262 1092,285 1105,310 L1116,346"],"fino":["M228,285 L83,213 M228,285 L114,208 M228,285 L157,206 M228,285 L190,204 M228,285 L235,203 M228,285 L277,209","M1105,310 C1135,345 1160,400 1176,430"],"botones":[[83,213,5],[114,208,5],[157,206,5],[190,204,5],[235,203,5],[277,209,5],[1118,350,7],[1109,345,6],[1176,433,6]],"lbl":[0,-36,"middle"]}},{"clave":"exc","nombre":"Interneurona excitatoria","detalle":"multipolar","icono":"Multipolar","color":"#16A34A","zona":{"p":[[[69.27,28.12],[69.08,28.42],[71.81,32.03],[72.4,33.69],[73.05,37.21],[73.18,41.41],[76.56,41.41],[76.56,40.43],[73.7,31.05],[72.59,29.59],[69.86,27.64],[69.6,28.32]]]},"zona_nombre":"Asta dorsal","punto":[73.89,36.62],"pista":"Está en el asta dorsal, donde termina la sensitiva del dolor.","exp":"Recibe a la sensitiva en el asta dorsal y excita a la motoneurona del flexor.","trazo":{"color":"#16A34A","ico":"Multipolar","soma":[1135,375,18],"d":["M1135,393 C1142,450 1135,520 1122,562"],"fino":[],"botones":[[1120,565,6],[1130,566,6]],"lbl":[28,-4,"start"]}},{"clave":"inhib","nombre":"Interneurona inhibitoria","detalle":"multipolar","icono":"Multipolar","color":"#7C3AED","zona":{"e":[[76.5,44.73,3.78,4.3]],"p":[]},"zona_nombre":"Sustancia gris intermedia","punto":[77.15,43.46],"pista":"Está en la sustancia gris, entre el asta dorsal y la ventral, cerca del canal central.","exp":"Recibe una colateral de la sensitiva y frena a la motoneurona del extensor.","trazo":{"color":"#7C3AED","ico":"Multipolar","soma":[1185,445,18],"d":["M1173,458 C1150,490 1100,520 1070,533"],"fino":[],"botones":[[1068,536,6],[1072,528,6]],"lbl":[28,-4,"start"]}},{"clave":"motora-flex","nombre":"Motoneurona del flexor","detalle":"multipolar","icono":"Motoneurona","color":"#EA580C","zona":{"p":[[[67.84,48.83],[66.67,50.78],[66.08,53.22],[66.34,56.45],[67.64,59.08],[69.34,60.45],[71.81,60.84],[73.83,59.96],[75.26,58.2],[77.21,51.86],[77.21,47.46],[69.4,47.46]]]},"zona_nombre":"Asta ventral","punto":[72.79,57.13],"pista":"Busca el asta ancha de la mariposa, la del lado de la raíz ventral.","exp":"Su soma está en el asta ventral y su axón sale por la raíz ventral y el nervio hasta la placa motora: es la vía final común.","trazo":{"color":"#EA580C","ico":"Motoneurona","soma":[1118,585,22],"d":["M1118,585 L1100,590 C1050,600 1000,598 965,598 C905,582 855,542 800,504 S705,462 625,460 C600,480 590,520 575,580 S500,650 430,690"],"fino":["M430,690 C390,700 340,705 300,715 M430,690 C400,715 360,735 325,755 M430,690 C415,730 400,760 388,790 M430,690 C440,730 450,760 457,793"],"botones":[[300,715,6],[325,755,6],[388,790,6],[457,793,6]],"lbl":[0,50,"middle"]},"dada":true},{"clave":"motora-ext","nombre":"Motoneurona del extensor","detalle":"multipolar","icono":"Motoneurona","color":"#DC2626","zona":{"p":[[[67.84,48.83],[66.67,50.78],[66.08,53.22],[66.34,56.45],[67.64,59.08],[69.34,60.45],[71.81,60.84],[73.83,59.96],[75.26,58.2],[77.21,51.86],[77.21,47.46],[69.4,47.46]]]},"zona_nombre":"Asta ventral","punto":[68.03,53.22],"pista":"Busca el asta ancha de la mariposa, la del lado de la raíz ventral.","exp":"Su soma está en el asta ventral y su axón sale por la raíz ventral y el nervio hasta la placa motora: es la vía final común.","trazo":{"color":"#DC2626","ico":"Motoneurona","soma":[1045,545,26],"d":["M1045,545 C1020,565 990,580 962,590 C905,572 855,530 800,494 S705,452 620,450 S500,438 470,440 C450,445 438,460 430,476"],"fino":[],"botones":[[424,484,6],[436,486,6],[430,492,6]],"lbl":[-36,-30,"end"]},"dada":true}],"vias":[{"titulo":"Vía de la retirada","orden":["sensitiva","exc","motora-flex"],"pista":"Del nociceptor a la interneurona del asta dorsal, y de ahí al músculo que aleja el pie.","exp":"Nociceptor → sensitiva → interneurona excitatoria (asta dorsal) → motoneurona del flexor → el flexor retira el pie.","ruta":"M228,285 C280,300 340,305 375,325 S430,395 470,418 S570,430 610,438 S700,420 740,395 S810,345 850,338 C880,315 920,285 960,268 S1040,238 1068,250 C1085,262 1092,285 1105,310 L1118,350 L1135,375 L1135,393 C1142,450 1135,520 1122,562 L1118,585 L1100,590 C1050,600 1000,598 965,598 C905,582 855,542 800,504 S705,462 625,460 C600,480 590,520 575,580 S500,650 430,690 C400,715 360,735 325,755"},{"titulo":"Inhibición recíproca","orden":["sensitiva","inhib","motora-ext"],"inhibe":"motora-ext","pista":"Ahora hay que relajar al músculo que se opone a la flexión.","exp":"Sensitiva → interneurona inhibitoria → motoneurona del extensor, que queda frenada.","ruta":"M228,285 C280,300 340,305 375,325 S430,395 470,418 S570,430 610,438 S700,420 740,395 S810,345 850,338 C880,315 920,285 960,268 S1040,238 1068,250 C1085,262 1092,285 1105,310 C1135,345 1160,400 1176,430 L1185,445 L1173,458 C1150,490 1100,520 1070,533 L1045,545"}],"lupas":[{"clave":"excitatoria","titulo":"Sinapsis excitatoria (celeste → verde)","img":"img/reflejo/sinapsis-excitatoria.jpg","x":1172,"y":318,"preguntas":[{"p":"¿Qué cambia en la interneurona verde cuando la celeste libera glutamato?","ops":["Se despolariza y puede disparar hacia la motoneurona","Se hiperpolariza y deja de disparar hacia la motoneurona","Libera acetilcolina directamente sobre el músculo flexor","Envía el impulso de vuelta hacia la neurona sensitiva"],"ok":0,"pista":"El glutamato es excitatorio.","exp":"El glutamato abre canales catiónicos (entra Na⁺): la interneurona se despolariza y excita a la motoneurona del flexor."},{"p":"¿Por qué el reflejo de retirada tarda un poco más que el rotuliano?","ops":["Tiene más sinapsis: cada una suma un retardo sináptico","Su receptor está más lejos de la médula que el huso","Su motoneurona no tiene mielina y conduce muy lento","La señal pasa primero por el encéfalo antes de volver"],"ok":0,"pista":"Cuenta las sinapsis entre la sensitiva y la motoneurona.","exp":"Es polisináptico: cada sinapsis agrega cerca de 0,5–1 ms. Aun así no pasa por el encéfalo."}]},{"clave":"inhibitoria","titulo":"Sinapsis inhibitoria (morada → roja)","img":"img/reflejo/sinapsis-inhibitoria.jpg","x":1112,"y":478,"preguntas":[{"p":"En la retirada, ¿qué motoneurona queda inhibida y por qué?","ops":["La del extensor, para que no se oponga al flexor","La del flexor, para que la pierna no se mueva","La del extensor, para que el huso deje de estirarse","La del flexor, para proteger el músculo del dolor"],"ok":0,"pista":"Ahora el que se contrae es el flexor.","exp":"Se invierte el rotuliano: el flexor se contrae y la interneurona inhibitoria frena al extensor (inhibición recíproca)."},{"p":"¿Qué distingue a una vesícula inhibitoria en la lupa?","ops":["Suele ser aplanada y contiene glicina o GABA","Es redonda y grande y contiene glutamato","Es densa y contiene acetilcolina para el músculo","No tiene contenido: sólo abre la hendidura"],"ok":0,"pista":"Compara la forma de las vesículas de las dos lupas sinápticas.","exp":"En la microscopía electrónica, las sinapsis inhibitorias suelen tener vesículas aplanadas (glicina o GABA) y las excitatorias, redondas (glutamato)."}]}],"preguntas":[{"p":"Al pisar el clavo contraes los flexores y a la vez se relajan los extensores. ¿Qué permite eso?","ops":["La interneurona, que reparte la señal: excita a unos y frena a otros","La sensitiva, que hace sinapsis directo con todos los músculos","La motoneurona, que envía órdenes opuestas por un solo axón","La raíz ventral, que separa las órdenes de contraer y relajar"],"ok":0,"pista":"¿Qué neurona tiene este circuito que el rotuliano no tiene?","exp":"Las interneuronas distribuyen la señal: excitan a las motoneuronas de los flexores e inhiben a las de los extensores (inervación recíproca). También pueden cruzar al otro lado para sostener el cuerpo."},{"p":"Retiras el pie antes de sentir el dolor. ¿Qué lo explica?","ops":["El circuito se cierra en la médula; la vía hacia el encéfalo es más larga","El dolor no llega al encéfalo hasta que el reflejo ya terminó","La interneurona bloquea el dolor mientras dura el movimiento","El encéfalo inicia el reflejo y después registra el dolor"],"ok":0,"pista":"¿Dónde se cierra el circuito que armaste? ¿Pasa por el encéfalo?","exp":"El reflejo se resuelve en el segmento medular. Al mismo tiempo, otras neuronas llevan la señal hacia el encéfalo, que la percibe como dolor un instante después."}]}]},{"n":5,"tipo":"circuito","titulo":"¿Dónde se cortó el arco?","fondo":"img/reflejo/esquema-base.jpg","vb":[1536,1024],"instrucciones":"Los tres pacientes tienen el <strong>reflejo rotuliano disminuido o ausente</strong>. Lee cada caso, tócalo y luego toca el sitio (A, B o C) donde está la lesión. Fíjate en lo que acompaña al reflejo: ¿falla la sensibilidad, la fuerza o ambas? <strong>Verde</strong>: correcto. <strong>Rojo</strong>: por repasar. <strong>Naranjo</strong>: lo que estás haciendo.","circuitos":[],"neuronas":[{"color":"#2563EB","ico":"Pseudounipolar","soma":[850,298,24],"d":["M292,500 C320,470 360,448 410,438 S560,432 610,440 S700,425 740,400 S810,345 850,338","M850,338 L850,322","M850,338 C880,315 920,285 960,268 S1040,238 1068,250 C1085,262 1092,285 1105,310 S1128,345 1132,370 C1136,420 1110,480 1080,512"],"fino":["M262,492 q8,-14 16,0 q8,14 16,0 q8,-14 16,0","M1133,395 C1145,420 1155,440 1160,458"],"botones":[[1080,512,7],[1069,509,6],[1088,519,6],[1160,462,6]],"lbl":[0,-36,"middle"]},{"color":"#DC2626","ico":"Motoneurona","soma":[1045,545,26],"d":["M1045,545 C1020,565 990,580 962,590 C905,572 855,530 800,494 S705,452 620,450 S500,438 470,440 C450,445 438,460 430,476"],"fino":[],"botones":[[424,484,6],[436,486,6],[430,492,6]],"lbl":[-36,-30,"end"]}],"cortes":{"titulo":"¿Dónde se cortó el arco?","sitios":[{"letra":"A","x":560,"y":445,"nombre":"Nervio (mixto)"},{"letra":"B","x":930,"y":262,"nombre":"Raíz dorsal y ganglio"},{"letra":"C","x":1098,"y":578,"nombre":"Asta ventral (motoneurona)"}],"casos":[{"titulo":"Hernia lumbar","caso":"Hombre de 45 años con una hernia del disco L3-L4 que comprime la raíz L4. Tiene dolor y hormigueo en la cara anterior de la pierna y el rotuliano disminuido; la fuerza para extender la rodilla está casi normal.","sitio":"B","respuesta":"Raíz dorsal (y su ganglio)","pista":"Predominan el dolor y el hormigueo: ¿qué parte del arco trae la información?","exp":"La hernia comprime la raíz posterior: falla la entrada sensitiva (dolor radicular en el dermatoma) y el reflejo disminuye, aunque la motoneurona esté sana. Si la compresión es intensa también puede haber algo de debilidad."},{"titulo":"Atrofia muscular espinal","caso":"Niña de 3 años con atrofia muscular espinal: debilidad y atrofia de los muslos, fasciculaciones y rotuliano ausente. Siente bien el tacto y el dolor.","sitio":"C","respuesta":"Asta ventral (motoneurona)","pista":"La sensibilidad está intacta y el músculo se atrofia. ¿Dónde están los somas de la vía final común?","exp":"La atrofia muscular espinal (como la poliomielitis) destruye las motoneuronas del asta ventral: se pierden el reflejo y la fuerza, el músculo se atrofia y fascicula, pero la sensibilidad queda intacta."},{"titulo":"Lesión del nervio femoral","caso":"Mujer de 60 años que, tras una cirugía de cadera, no puede extender la rodilla, no tiene rotuliano y no siente la cara anterior del muslo.","sitio":"A","respuesta":"Nervio (mixto)","pista":"Fallan a la vez la sensibilidad y la fuerza del mismo territorio.","exp":"El nervio femoral lleva juntas las fibras sensitivas y las motoras del cuádriceps: su lesión quita sensibilidad, fuerza y reflejo en su territorio."}]}}]}', NULL, 1);

-- Actividad 10: CONOCE LA GLÍA (práctico 2) · ESTRUCTURA Y UBICACIÓN sobre esquemas. Niveles I-II «circuito» con etiquetas
-- (nombre por clic, zonas sombreadas y preguntas de forma o lugar; II usa img/glia-snp-tejido.jpg, ganglio → nervio);
-- nivel III práctica «elegir» con tarjetas de las 6 glías: descripción de forma o lugar → tarjeta → cuadro (sin funciones: van en «La glía en acción»)
INSERT OR IGNORE INTO actividades (id, topic_id, slug, titulo, descripcion, tipo, activo, objetivo, mecanica, fuente) VALUES
  (10, 7, 'glia-conoce', 'Conoce la glía',
       'Las seis células gliales: cómo son y dónde están. Nivel I: la glía del SNC en su tejido. Nivel II: la glía del SNP, del ganglio al nervio. Nivel III: reconoce cada célula por su forma y su lugar y arma el cuadro.',
       'lamina', 1, 'Reconocer las células gliales del SNC y del SNP por su forma y su ubicación en el tejido.', 'Etiquetar dos esquemas tocando cada estructura; leer descripciones de forma y lugar y tocar la tarjeta de la célula para completar un cuadro.', 'Clase Células del sistema nervioso II 2026 · esquemas de Kaira Santos y Fernanda López');
INSERT OR IGNORE INTO actividad_recursos (actividad_id, tipo, url, caption, orden) VALUES
  (10, 'tareas', '{"laminas": {}, "niveles": [{"n": 1, "tipo": "circuito", "titulo": "Glía del SNC en su tejido", "fondo": "img/glia-snc-tejido.jpg", "etiquetas": true, "subtitulo": "La glía del SNC en su tejido", "instrucciones": "Primero ubica la <strong>sustancia gris</strong> y la <strong>sustancia blanca</strong> (las dos zonas sombreadas). Después elige cada nombre en el panel y toca la célula en el esquema; al final, mira el esquema y responde. <strong>Verde</strong>: correcto. <strong>Rojo</strong>: por repasar. <strong>Naranjo</strong>: lo que estás haciendo.", "circuitos": [{"clave": "zonas", "titulo": "Sustancia gris y blanca", "ayuda": "Elige un nombre y toca su zona sombreada en la imagen.", "mascara": [{"r": [0, 0, 47, 76], "c": "rgba(124,58,237,.38)"}, {"r": [53, 0, 47, 76], "c": "rgba(13,148,136,.38)"}], "piezas": [{"clave": "gris", "nombre": "Sustancia gris", "zona": {"r": [[0, 0, 49, 76]]}, "punto": [22, 40], "pista": "Es el lado donde están los somas de las neuronas y sus sinapsis.", "exp": "Somas, dendritas y sinapsis: aquí se procesa la información."}, {"clave": "blanca", "nombre": "Sustancia blanca", "zona": {"r": [[51, 0, 49, 76]]}, "punto": [78, 40], "pista": "Es el lado de los axones paralelos envueltos en mielina.", "exp": "Axones mielinizados que conducen la información entre regiones; la mielina le da su color blanco."}], "preguntas": []}, {"clave": "celulas", "titulo": "Las células", "ayuda": "Elige un nombre y toca la célula en la imagen (vale cualquier punto de la célula).", "piezas": [{"clave": "neurona", "nombre": "Neurona", "zona": {"e": [[16, 25, 7, 9], [24, 55, 6.5, 8]]}, "punto": [16, 25], "pista": "Es la célula violeta grande, con soma, dendritas y un axón que se mieliniza.", "exp": "No es glía: es la célula que la glía sostiene y protege."}, {"clave": "astro-proto", "nombre": "Astrocito protoplasmático", "zona": {"e": [[36.5, 31, 5, 7]]}, "punto": [36.5, 31], "pista": "Es la célula rosada en estrella de la sustancia gris, junto al capilar.", "exp": "Astrocito de la sustancia gris: muchas ramas cortas que rodean a las neuronas."}, {"clave": "astro-fibroso", "nombre": "Astrocito fibroso", "zona": {"e": [[92, 31, 6, 9]]}, "punto": [92, 31], "pista": "Es la célula rosada en estrella de la sustancia blanca, de ramas largas y rectas.", "exp": "Astrocito de la sustancia blanca: ramas largas entre los axones."}, {"clave": "oligo", "nombre": "Oligodendrocito", "zona": {"e": [[73.5, 40.5, 4.5, 6.5]]}, "punto": [73.5, 40.5], "pista": "Es la célula azul de la sustancia blanca: sus prolongaciones llegan a la mielina de varios axones.", "exp": "Forma la mielina de varios axones del SNC."}, {"clave": "microglia", "nombre": "Microglía", "zona": {"e": [[41, 54, 5, 7], [56.5, 12, 5, 7]]}, "punto": [41, 54], "pista": "Es la célula más pequeña, gris azulada y muy ramificada (hay dos).", "exp": "La célula de defensa del SNC."}, {"clave": "ependimaria", "nombre": "Célula ependimaria", "zona": {"r": [[0, 76, 100, 10]]}, "punto": [45, 81.5], "pista": "Son las células amarillas en fila que revisten la cavidad de abajo.", "exp": "Revisten los ventrículos y el canal central."}, {"clave": "capilar", "nombre": "Capilar", "zona": {"e": [[45.5, 14, 4.5, 11]]}, "punto": [45.5, 14], "pista": "Es el vaso con glóbulos rojos, arriba.", "exp": "Vaso sanguíneo: los astrocitos lo rodean con sus pies."}], "preguntas": [{"p": "En el esquema hay dos astrocitos, uno en cada sustancia. ¿Qué diferencia su forma?", "ops": ["El de la gris tiene ramas cortas y muy ramificadas; el de la blanca, ramas largas y rectas", "El de la gris no tiene núcleo; el de la blanca tiene un núcleo grande y central", "El de la gris envuelve axones con mielina; el de la blanca rodea los somas", "Son iguales: sólo cambia el color con que se dibujó cada uno"], "ok": 0, "pista": "Compara el largo y la cantidad de ramas de las dos células rosadas.", "exp": "Protoplasmático (sustancia gris): ramas cortas y muy ramificadas entre somas y sinapsis. Fibroso (sustancia blanca): ramas largas y rectas entre los axones."}, {"p": "Sigue las prolongaciones del oligodendrocito. ¿A cuántos axones llegan?", "ops": ["A varios axones: cada prolongación forma un tramo de mielina en un axón distinto", "A un solo axón: la célula se enrolla entera alrededor de él", "A ninguno: sus prolongaciones terminan en el capilar", "A los somas de las neuronas de la sustancia gris"], "ok": 0, "pista": "Cuenta los axones celestes que toca la célula azul.", "exp": "Un oligodendrocito mieliniza tramos (internodos) de varios axones a la vez: hasta unos 50."}, {"p": "Además de rodear a las neuronas, ¿con qué estructura se relacionan los pies de los astrocitos?", "ops": ["Con el capilar: sus pies lo rodean por fuera", "Con la cavidad del ventrículo: la tapizan por dentro", "Con la mielina: la fabrican en la sustancia blanca", "Con la microglía: la envuelven para que no se mueva"], "ok": 0, "pista": "Mira qué toca el astrocito protoplasmático en la parte de arriba.", "exp": "Los pies perivasculares cubren casi todo el contorno de los capilares: así el astrocito queda entre la sangre y la neurona."}, {"p": "Las células ependimarias forman una fila continua. ¿Hacia dónde apuntan sus cilios?", "ops": ["Hacia la cavidad con líquido (ventrículo o canal central)", "Hacia la sustancia blanca, entre los axones", "Hacia el capilar, para tocar la sangre", "Hacia el soma de la neurona más cercana"], "ok": 0, "pista": "Mira la parte de abajo del esquema.", "exp": "El epéndimo es un epitelio de una capa: su cara con cilios y microvellosidades mira al líquido cefalorraquídeo."}]}]}, {"n": 2, "tipo": "circuito", "titulo": "Glía del SNP en su tejido", "fondo": "img/glia-snp-tejido.jpg", "etiquetas": true, "subtitulo": "La glía del SNP en su tejido", "instrucciones": "A la izquierda, un <strong>ganglio sensitivo</strong>; a la derecha, el <strong>nervio</strong> que sale de él. Primero ubica las dos zonas; después elige cada nombre y tócalo en el esquema; al final, responde. <strong>Verde</strong>: correcto. <strong>Rojo</strong>: por repasar. <strong>Naranjo</strong>: lo que estás haciendo.", "circuitos": [{"clave": "zonas", "titulo": "Ganglio y nervio", "ayuda": "Elige un nombre y toca su zona sombreada en el esquema.", "mascara": [{"r": [0, 2, 47, 84], "c": "rgba(124,58,237,.32)"}, {"r": [49, 18, 51, 58], "c": "rgba(13,148,136,.32)"}], "piezas": [{"clave": "ganglio", "nombre": "Ganglio sensitivo", "zona": {"r": [[0, 2, 48, 84]]}, "punto": [22, 82], "pista": "Es la zona de los somas redondos y grandes.", "exp": "Agrupación de somas neuronales fuera del SNC (p. ej. el ganglio de la raíz dorsal)."}, {"clave": "nervio", "nombre": "Nervio periférico", "zona": {"r": [[48, 18, 52, 58]]}, "punto": [75, 72], "pista": "Es la zona de los axones en paralelo, sin somas.", "exp": "Haz de axones que van y vienen del ganglio, envueltos por células de Schwann."}], "preguntas": []}, {"clave": "celulas", "titulo": "Las células", "ayuda": "Elige un nombre y toca su lugar en el esquema (vale cualquier punto de esa estructura).", "piezas": [{"clave": "neurona-g", "nombre": "Soma de neurona", "zona": {"e": [[10.5, 22, 6, 9.5], [32.3, 27, 6, 9], [13.5, 52, 6.5, 9.5], [30.5, 62, 6, 9]]}, "punto": [10.5, 22], "pista": "Es el soma violeta grande y redondo (hay cuatro).", "exp": "Soma de una neurona pseudounipolar: está en el ganglio, fuera del SNC."}, {"clave": "satelite", "nombre": "Célula satélite", "zona": {"e": [[10.5, 22, 9.5, 14], [32.3, 27, 9, 13.5], [13.5, 52, 10, 14], [30.5, 62, 9.5, 14]], "no": {"e": [[10.5, 22, 6, 9.5], [32.3, 27, 6, 9], [13.5, 52, 6.5, 9.5], [30.5, 62, 6, 9]]}}, "punto": [5, 50], "pista": "Son las células aplanadas, color crema, en anillo alrededor de cada soma.", "exp": "Forman una cápsula alrededor de cada soma del ganglio."}, {"clave": "axon", "nombre": "Axón", "zona": {"e": [[41, 43, 6, 2.6], [54, 49, 5, 3.5]]}, "punto": [41, 43], "pista": "Es la prolongación violeta que sale del soma y entra al nervio.", "exp": "La única prolongación de la neurona pseudounipolar, que luego se divide en dos ramas."}, {"clave": "schwann-m", "nombre": "Célula de Schwann mielinizante", "zona": {"e": [[66.5, 35.5, 6.3, 3.2], [81.7, 30.8, 6.7, 3.4], [69.8, 42, 5.9, 3], [83.2, 38.3, 5.9, 2.7], [95.5, 35.5, 4.6, 3.4], [95.2, 27, 4.8, 2.7], [54.2, 38.5, 4.3, 2.5], [56.7, 44.2, 5.7, 2.2], [65.4, 52.7, 5.4, 2.5], [79, 53.2, 6.5, 2.5], [91.3, 52.5, 4.3, 2.5]]}, "punto": [66.5, 35.5], "pista": "Son los segmentos celestes, uno detrás de otro, a lo largo de un axón.", "exp": "Cada una envuelve un solo tramo (internodo) de un solo axón."}, {"clave": "nodo", "nombre": "Nodo de Ranvier", "zona": {"e": [[74.1, 33.5, 1.6, 2.4], [59.1, 37.6, 1.6, 2.4], [63.3, 43.6, 1.6, 2.4], [76.6, 40.2, 1.6, 2.4], [89.4, 28.3, 1.6, 2.4], [90, 37.1, 1.6, 2.4], [71.7, 53.2, 1.6, 2.4], [86.3, 53.2, 1.6, 2.4], [96.4, 51.1, 1.6, 2.4]]}, "punto": [71.7, 53.2], "pista": "Es el tramo corto, violeta, entre dos células de Schwann.", "exp": "Tramo de axón sin mielina entre dos células de Schwann."}, {"clave": "schwann-nm", "nombre": "Célula de Schwann no mielinizante", "zona": {"e": [[77.5, 61.4, 7.8, 5]]}, "punto": [75, 60], "pista": "Es la célula celeste de abajo con varios axones delgados hundidos en ella.", "exp": "Envuelve varios axones delgados sin formar capas de mielina (fibra de Remak)."}, {"clave": "capilar", "nombre": "Capilar", "zona": {"e": [[89, 45, 11, 3.3], [80, 46.5, 4, 2.3]]}, "punto": [89, 45], "pista": "Es el vaso con glóbulos rojos dentro del nervio.", "exp": "Vaso sanguíneo que irriga el nervio."}, {"clave": "conectivo", "nombre": "Tejido conectivo", "zona": {"r": [[0, 1, 46, 6], [0, 73, 42, 11], [52, 21, 22, 5], [50, 67, 50, 6]]}, "punto": [20, 78], "pista": "Es el tejido rosado y fibroso que rodea al ganglio y al nervio.", "exp": "Cápsula del ganglio y envolturas del nervio: sostienen y protegen a neuronas y glía."}], "preguntas": [{"p": "En el ganglio, ¿cómo se relacionan los somas vecinos?", "ops": ["Cada soma tiene su propia cápsula de células satélite y no toca a los otros", "Los somas se tocan directamente y se unen por sinapsis entre ellos", "Una sola célula satélite envuelve a los cuatro somas a la vez", "Los somas están sueltos en el tejido conectivo, sin glía alrededor"], "ok": 0, "pista": "Mira el anillo color crema de cada soma.", "exp": "En el ganglio cada soma queda dentro de su propia cápsula de células satélite: no hay contacto directo entre somas vecinos."}, {"p": "Compara la célula de Schwann mielinizante con el oligodendrocito del nivel I. ¿Qué cambia?", "ops": ["Cada Schwann envuelve un solo tramo de un axón; el oligodendrocito, tramos de varios axones", "La Schwann envuelve varios axones; el oligodendrocito, un solo tramo de un axón", "La Schwann no forma mielina; sólo el oligodendrocito la forma", "Son la misma célula: cambia el nombre según el lugar del cuerpo"], "ok": 0, "pista": "Cuenta cuántas células de Schwann hay a lo largo de un mismo axón.", "exp": "SNP: una célula de Schwann = un internodo de un axón (un axón largo necesita cientos en fila). SNC: un oligodendrocito = internodos de muchos axones."}, {"p": "Mira la célula de Schwann no mielinizante. ¿Qué tiene dentro?", "ops": ["Varios axones delgados hundidos en su citoplasma, sin capas de mielina", "Un solo axón grueso envuelto por muchas capas de mielina", "El soma de una neurona, como las células satélite", "Glóbulos rojos, porque es parte del capilar"], "ok": 0, "pista": "Busca la célula celeste de abajo con varios círculos violeta dentro.", "exp": "Es una fibra de Remak: una célula de Schwann aloja varios axones delgados (como los del dolor lento) sin mielinizarlos."}]}]}, {"n": 3, "tipo": "practica", "titulo": "¿Quién es quién? Forma y lugar"}]}', NULL, 1);
INSERT OR IGNORE INTO practica_niveles (id, actividad_id, numero, titulo, instrucciones, tipo, activo) VALUES
  (3, 10, 3, '¿Quién es quién? Forma y lugar', 'Lee la descripción y toca la tarjeta de la célula. Cada acierto escribe una celda del cuadro: primero la <strong>forma</strong>, después <strong>dónde está</strong>. <strong>Rojo</strong>: esa no era; lee la pista y prueba con otra.', 'elegir', 1);
INSERT OR IGNORE INTO practica_items (nivel_id, enunciado, respuesta, sinonimos, pista, explicacion, orden, fila, celda, nota, datos) VALUES
  (3, 'Cuerpo pequeño y alargado, con ramas finas y espinosas que se mueven por el tejido.', 'Microglía', 'microglia',
      'Es la más pequeña de la glía del SNC.',
      'Sus ramas exploran el tejido todo el tiempo, aunque no haya daño.', 1, 'Forma', 'Pequeña, ramas finas y espinosas', NULL, NULL),
  (3, 'Forma de estrella: muchas prolongaciones que terminan en pies ensanchados.', 'Astrocito', 'astrocitos',
      'Su nombre significa «célula estrella».',
      'Sus pies se apoyan en capilares, sinapsis y nodos.', 2, 'Forma', 'Estrella con pies', NULL, NULL),
  (3, 'Cuerpo pequeño y redondo con varias prolongaciones; cada una se aplana y se enrolla en un axón distinto.', 'Oligodendrocito', 'oligodendrocitos',
      'Una sola célula del SNC forma mielina en muchos axones a la vez.',
      'Cada prolongación forma un internodo de mielina: una sola célula puede mielinizar hasta unos 50 axones.', 3, 'Forma', 'Varias ramas, cada una a un axón', NULL, NULL),
  (3, 'Cúbica o cilíndrica, con cilios, unida a sus vecinas en una sola capa.', 'Célula ependimaria', 'ependimaria|ependimarias',
      'Es la única glía con forma de epitelio.',
      'Forma el epéndimo, un epitelio cúbico simple.', 4, 'Forma', 'Epitelio cúbico con cilios', NULL, NULL),
  (3, 'Se enrolla muchas veces alrededor de un solo tramo de un axón.', 'Célula de Schwann', 'schwann|celula de schwann',
      'Una célula, un tramo, un axón.',
      'Un axón largo necesita cientos de ellas en fila.', 5, 'Forma', 'Se enrolla en 1 tramo de 1 axón', NULL, NULL),
  (3, 'Pequeña y aplanada; junto a otras forma un anillo alrededor de un soma.', 'Célula satélite', 'satelite|satelites',
      'Piensa en el anillo color crema del nivel II.',
      'Varias células satélite forman la cápsula de cada soma.', 6, 'Forma', 'Aplanada, en anillo', NULL, NULL),
  (3, 'Tapiza los ventrículos del encéfalo y el canal central de la médula.', 'Célula ependimaria', 'ependimaria|ependimarias',
      'Busca la glía que reviste cavidades con líquido.',
      'Está en contacto con el líquido cefalorraquídeo.', 7, 'Dónde está', 'Ventrículos y canal central', NULL, NULL),
  (3, 'Rodea el soma de cada neurona en los ganglios sensitivos y autonómicos.', 'Célula satélite', 'satelite|satelites',
      'Estás fuera del SNC, en un ganglio.',
      'Es glía del SNP. Rodea a las neuronas pseudounipolares de los ganglios sensitivos y también a las multipolares de los ganglios autónomos (simpáticos y parasimpáticos).', 8, 'Dónde está', 'Ganglios (SNP)', NULL, NULL),
  (3, 'En el SNC, sobre todo en la sustancia blanca, en hileras entre los axones.', 'Oligodendrocito', 'oligodendrocitos',
      'Busca la glía que acompaña a los axones dentro del SNC.',
      'Sus núcleos se ven en hileras entre las fibras.', 9, 'Dónde está', 'Sustancia blanca (SNC)', NULL, NULL),
  (3, 'En la sustancia gris y en la blanca; sus pies cubren los capilares.', 'Astrocito', 'astrocitos',
      'Hay un tipo en cada sustancia.',
      'Protoplasmático en la gris y fibroso en la blanca.', 10, 'Dónde está', 'Gris y blanca (SNC)', NULL, NULL),
  (3, 'A lo largo de los axones de los nervios, desde la raíz hasta el músculo.', 'Célula de Schwann', 'schwann|celula de schwann',
      'Estás en el nervio periférico.',
      'Es glía del SNP.', 11, 'Dónde está', 'Nervios (SNP)', NULL, NULL),
  (3, 'Repartida de forma pareja por todo el SNC: cada célula vigila su propia zona, sin superponerse con sus vecinas. Es la única glía que no nace del tejido nervioso.', 'Microglía', 'microglia',
      'Piensa en la glía de defensa: nace de los mismos precursores que los macrófagos de la sangre.',
      'Nace del mesodermo (precursores inmunes) y entra al SNC durante el desarrollo.', 12, 'Dónde está', 'Todo el SNC · origen inmune', NULL, NULL);

-- Actividad 11: LA GLÍA EN EL TEJIDO (práctico 2). Niveles I-III capturas en láminas reales (médula H&E, médula cresil, ganglio y nervio); nivel IV práctica «elegir» con imágenes de inmunofluorescencia de Wikimedia Commons (img/glia-if/, con autor y licencia en el pie)
INSERT OR IGNORE INTO actividades (id, topic_id, slug, titulo, descripcion, tipo, activo, objetivo, mecanica, fuente) VALUES
  (11, 7, 'glia-tejido', 'La glía en el tejido',
       'Encuentra la glía en cortes reales. Nivel I: el canal central y la sustancia blanca de la médula. Nivel II: la motoneurona y la glía que la rodea. Nivel III: las células satélite del ganglio y las envolturas del nervio. Nivel IV: reconoce cada glía en imágenes con anticuerpos.',
       'lamina', 1, 'Reconocer la glía del SNC y del SNP en cortes reales por su forma, su ubicación y lo que la rodea.', 'Buscar, capturar, recortar, etiquetar y responder en cuatro láminas reales.', 'Clase Células del sistema nervioso II 2026 · MHS-240, UCSF-163, MH-051 y MH-052 (histologyguide.com)');
INSERT OR IGNORE INTO actividad_recursos (actividad_id, tipo, url, caption, orden) VALUES
  (11, 'tareas', '{"laminas": {"mhs240": {"nombre": "H&E (conejo)", "url": "https://histologyguide.com/slideview/MHS-240-spinal-cord/06-slide-1.html?x=8910&y=6975&z=5.786", "caption": "Médula espinal de conejo — H&E (histologyguide.com)"}, "ucsf163": {"nombre": "Cresil violeta (gato)", "url": "https://histologyguide.com/slideview/UCSF-163-spinal-cord/06-slide-1.html?x=12976&y=9803&z=4.400", "caption": "Médula espinal de gato — cresil violeta (histologyguide.com)"}, "mh051": {"nombre": "Azan (ganglio)", "url": "https://histologyguide.com/slideview/MH-051-dorsal-root-ganglion/06-slide-1.html?x=8730&y=6571&z=6.082", "caption": "Ganglio de la raíz dorsal — Azan (histologyguide.com)"}, "mh052": {"nombre": "H&E (nervio)", "url": "https://histologyguide.com/slideview/MH-052-peripheral-nerve/06-slide-1.html?x=18642&y=16157&z=4.930", "caption": "Nervio periférico — H&E (histologyguide.com)"}}, "niveles": [{"n": 1, "tipo": "capturas", "titulo": "Canal central y sustancia blanca", "laminas": ["mhs240"], "instrucciones": "Para cada captura sigue los pasos del panel: buscar y capturar, recortar, etiquetar y responder. Las preguntas se responden mirando tu captura. <strong>Verde</strong>: correcto. <strong>Rojo</strong>: por repasar. <strong>Naranjo</strong>: lo que estás haciendo.", "capturas": [{"clave": "canal-central", "objeto": "la zona", "titulo": "Canal central", "lamina": "mhs240", "busca": "Acércate al centro de la médula, donde se cruzan las astas de la sustancia gris: busca un pequeño orificio y acércate hasta ver las células que forman su borde.", "etiquetas": ["Canal central", "Células ependimarias", "Sustancia gris"], "preguntas": [{"p": "Alrededor del canal central ves una sola capa de células cúbicas, bien juntas. ¿Qué glía es?", "ops": ["Células ependimarias: el epitelio que tapiza el canal central", "Oligodendrocitos en fila que envuelven el borde del canal", "Neuronas pequeñas que rodean la cavidad", "Microglía que se juntó alrededor del canal"], "ok": 0, "pista": "Es la misma fila de células del borde inferior del esquema del nivel I de «Conoce la glía».", "exp": "Es el epéndimo: un epitelio cúbico simple de células ependimarias. Tapiza el canal central de la médula y, más arriba, los ventrículos del encéfalo."}, {"p": "¿En qué parte de la médula está el canal central?", "ops": ["Al centro de la sustancia gris, donde se unen sus dos mitades", "En el borde externo de la sustancia blanca", "Dentro del asta ventral, junto a las motoneuronas", "Fuera de la médula, en la raíz dorsal"], "ok": 0, "pista": "Ubícalo en la vista completa de la lámina, sin zoom.", "exp": "El canal central queda en la comisura gris, al centro de la «H» o «mariposa» de sustancia gris."}]}, {"clave": "sustancia-blanca", "objeto": "la zona", "titulo": "Sustancia blanca", "lamina": "mhs240", "busca": "Desde el centro, baja hacia el borde anterior de la médula, a la zona más clara y sin somas grandes. Acércate hasta ver núcleos pequeños y oscuros entre las fibras.", "etiquetas": ["Fibras nerviosas", "Núcleos de glía"], "preguntas": [{"p": "En la sustancia blanca ves núcleos pequeños y oscuros entre las fibras. ¿Cómo sabes que no son neuronas?", "ops": ["Son pequeños y no tienen alrededor un soma grande con citoplasma", "Son grandes y claros, con un nucléolo muy marcado", "Están dentro de los axones, donde las neuronas tienen su núcleo", "Se ven rosados, y los núcleos de neurona siempre son morados"], "ok": 0, "pista": "Compáralos con un soma de neurona de la sustancia gris.", "exp": "La neurona tiene un soma grande, con un núcleo claro y un nucléolo visible. En la sustancia blanca casi no hay somas: los núcleos pequeños son de glía."}, {"p": "Muchos de esos núcleos se ordenan en hileras entre las fibras. ¿Qué glía forma esas hileras?", "ops": ["Oligodendrocitos, que mielinizan los axones vecinos", "Células ependimarias, que tapizan la sustancia blanca", "Células satélite, que rodean cada axón", "Células de Schwann, que envuelven los tractos de la médula"], "ok": 0, "pista": "Recuerda qué glía del SNC acompaña a los axones mielinizados.", "exp": "Son oligodendrocitos interfasciculares, en fila entre los axones que mielinizan. Las células de Schwann y las satélite sólo están en el SNP."}]}]}, {"n": 2, "tipo": "capturas", "titulo": "Motoneurona y su glía", "laminas": ["ucsf163"], "instrucciones": "Para cada captura sigue los pasos del panel: buscar y capturar, recortar, etiquetar y responder. Las preguntas se responden mirando tu captura. <strong>Verde</strong>: correcto. <strong>Rojo</strong>: por repasar. <strong>Naranjo</strong>: lo que estás haciendo.", "capturas": [{"clave": "motoneurona", "titulo": "Motoneurona del asta ventral", "lamina": "ucsf163", "busca": "En la parte ancha y anterior de la sustancia gris, busca el soma más grande que encuentres y acércate hasta ver su núcleo, sus prolongaciones y lo que lo rodea.", "etiquetas": ["Soma", "Núcleo", "Prolongación", "Núcleos de glía", "Neuropilo"], "preguntas": [{"p": "Alrededor del soma de la motoneurona ves varios núcleos pequeños pegados a su borde. ¿Qué son?", "ops": ["Núcleos de glía que rodean a la neurona (glía perineuronal)", "Núcleos extra de la motoneurona, que tiene varios", "Botones terminales de otras neuronas, teñidos de violeta", "Células de Schwann que forman mielina sobre el soma"], "ok": 0, "pista": "¿Una neurona tiene uno o varios núcleos? ¿Qué células acompañan a las neuronas en el SNC?", "exp": "Son núcleos de glía, sobre todo oligodendrocitos y astrocitos perineuronales. La motoneurona tiene un solo núcleo, grande y claro. Las células de Schwann sólo están en el SNP."}, {"p": "Compara estos núcleos de glía con los de la sustancia blanca del nivel I. ¿Qué cambió?", "ops": ["Su ubicación: aquí rodean un soma; allá van en hileras entre fibras", "Su tamaño: aquí son tan grandes como el núcleo de la neurona", "Su número: aquí no hay glía, sólo neuronas", "Nada: en la sustancia gris no hay núcleos de glía"], "ok": 0, "pista": "Piensa en qué acompaña la glía en cada zona.", "exp": "La misma glía del SNC se ubica según lo que acompaña: junto a somas en la sustancia gris (perineuronal) y en hileras entre axones en la sustancia blanca."}, {"p": "Entre los somas hay un fondo con pocos núcleos (neuropilo). ¿De qué está formado?", "ops": ["Dendritas, axones y prolongaciones de glía que se entrelazan", "Líquido cefalorraquídeo que se coaguló al fijar el tejido", "Mielina de la sustancia blanca que se mezcla con la gris", "Somas pequeños que el colorante no alcanzó a teñir"], "ok": 0, "pista": "Entre somas y núcleos, ¿qué otras partes de las células quedan?", "exp": "El neuropilo es la red de dendritas, axones, sinapsis y prolongaciones de astrocitos y microglía. Ahí ocurre la mayoría de las sinapsis de la sustancia gris."}]}]}, {"n": 3, "tipo": "capturas", "titulo": "Ganglio y nervio periférico", "laminas": ["mh051", "mh052"], "instrucciones": "Para cada captura sigue los pasos del panel: buscar y capturar, recortar, etiquetar y responder. Las preguntas se responden mirando tu captura. <strong>Verde</strong>: correcto. <strong>Rojo</strong>: por repasar. <strong>Naranjo</strong>: lo que estás haciendo.", "capturas": [{"clave": "ganglio", "titulo": "Neurona del ganglio", "lamina": "mh051", "busca": "Busca los somas grandes y redondos agrupados entre haces de fibras; acércate a uno hasta ver qué lo rodea.", "etiquetas": ["Soma neuronal", "Núcleo", "Células satélite", "Haz de fibras"], "preguntas": [{"p": "Cada soma del ganglio tiene un anillo de núcleos pequeños, como la motoneurona del nivel II. ¿Cuál es la diferencia?", "ops": ["Aquí son células satélite y estás fuera del SNC, en un ganglio", "Aquí son oligodendrocitos, igual que alrededor de la motoneurona", "Aquí son células de Schwann que forman mielina sobre el soma", "Aquí son fibroblastos de la cápsula que envuelve todo el ganglio"], "ok": 0, "pista": "¿Este corte es del SNC o del SNP? ¿Qué glía corresponde a cada uno?", "exp": "En el ganglio cada soma está envuelto por células satélite (SNP). Alrededor de la motoneurona (SNC) la glía es oligodendrocitos y astrocitos. Los dos se ven como un anillo de núcleos: lo que cambia es dónde estás."}, {"p": "Los somas del ganglio se ven redondos y casi sin prolongaciones, a diferencia de la motoneurona. ¿Por qué?", "ops": ["Son pseudounipolares: su única prolongación rara vez queda en el corte", "Son neuronas inmaduras que todavía no forman dendritas ni axón", "Sí tienen muchas ramas, pero la tinción sólo muestra el soma", "Son células gliales grandes, no neuronas, y por eso no tienen ramas"], "ok": 0, "pista": "Recuerda cuántas prolongaciones salen del soma de una neurona del ganglio de la raíz dorsal.", "exp": "Del soma de la neurona pseudounipolar sale una sola prolongación, que luego se divide en T. Como es una sola, pocas veces queda en el plano del corte."}]}, {"clave": "nervio", "objeto": "la zona", "titulo": "Nervio en corte transversal", "lamina": "mh052", "busca": "Mira las envolturas del nervio entero, de cada grupo de fibras (fascículo) y de cada fibra. Acércate a un fascículo hasta ver círculos claros con un punto al centro.", "etiquetas": ["Epineuro", "Perineuro", "Fascículo", "Endoneuro", "Fibra mielinizada"], "preguntas": [{"p": "Cada fibra mielinizada se ve como un círculo claro con un punto al centro. ¿Qué es cada parte?", "ops": ["El punto es el axón y el halo claro es el lugar que ocupa la mielina", "El punto es el núcleo de Schwann y el halo, su citoplasma", "El punto es un capilar y el halo, la sangre que lo rodea", "El punto es la mielina y el halo, el axón hinchado"], "ok": 0, "pista": "¿Qué va al centro de una fibra mielinizada y qué la envuelve?", "exp": "El axón queda al centro y la mielina lo rodea; al procesar el tejido sus lípidos se pierden y queda un halo claro."}, {"p": "En el corte ves núcleos grandes pegados a un axón y otros pequeños entre las fibras. ¿De qué células son?", "ops": ["Los grandes, de células de Schwann; los pequeños, de fibroblastos", "Los grandes, de fibroblastos; los pequeños, de células de Schwann", "Los grandes, de neuronas; los pequeños, de células de Schwann", "Los grandes, de oligodendrocitos; los pequeños, de fibroblastos"], "ok": 0, "pista": "En un nervio no hay somas de neuronas. ¿Qué célula va pegada a cada axón?", "exp": "El núcleo de la célula de Schwann queda al lado del axón que envuelve. Los pequeños son de fibroblastos del endoneuro. En un nervio no hay somas neuronales y los oligodendrocitos están en el SNC."}, {"p": "¿Qué envoltura rodea a cada grupo de fibras (fascículo)?", "ops": ["El perineuro", "El epineuro", "El endoneuro", "La mielina"], "ok": 0, "pista": "Epi = sobre todo el nervio; peri = alrededor del fascículo; endo = dentro, en cada fibra.", "exp": "Epineuro: todo el nervio. Perineuro: cada fascículo (sus células unidas forman la barrera hemato-nerviosa). Endoneuro: cada fibra."}]}]}, {"n": 4, "tipo": "practica", "titulo": "Glía con anticuerpos"}]}', NULL, 1);
INSERT OR IGNORE INTO practica_niveles (id, actividad_id, numero, titulo, instrucciones, tipo, activo) VALUES
  (5, 11, 4, 'Glía con anticuerpos', 'Cada imagen es real: un anticuerpo se une a una proteína de una célula y la pinta de un color. Mira la <strong>forma</strong> y el <strong>lugar</strong> de lo marcado y toca la tarjeta de la célula; el pie de la imagen dice qué marca cada color. <strong>Rojo</strong>: esa no era; lee la pista y prueba con otra.', 'elegir', 1);
INSERT OR IGNORE INTO practica_items (nivel_id, enunciado, respuesta, sinonimos, pista, explicacion, orden, fila, celda, nota, datos) VALUES
  (5, 'Cultivo de células nerviosas. Mira la forma de la célula amarilla: un cuerpo central con muchas prolongaciones largas, como una estrella. ¿Qué célula es?', 'Astrocito', 'astrocitos|astroglia',
      'Su nombre significa «célula estrella».',
      'El anticuerpo marca GFAP, un filamento intermedio propio de los astrocitos: por eso con él se ven completos.', 1, NULL, NULL, NULL, '{"img": "img/glia-if/astrocito-gfap.jpg", "pie": "GFAP (amarillo) · núcleos (azul). GerryShaw, CC BY-SA 3.0, Wikimedia Commons"}'),
  (5, 'Corte de encéfalo humano. Las prolongaciones cafés convergen y rodean un vaso sanguíneo. ¿Qué célula forma esos pies alrededor del vaso?', 'Astrocito', 'astrocitos|astroglia',
      'Busca la glía que se ubica entre el vaso y la neurona.',
      'Son los pies perivasculares de los astrocitos (marcados con GFAP), como en el esquema del nivel I de «Conoce la glía».', 2, NULL, NULL, NULL, '{"img": "img/glia-if/astrocito-capilar-ihq.jpg", "pie": "GFAP, inmunohistoquímica (café), encéfalo humano. Jensflorian, CC BY-SA 4.0, Wikimedia Commons"}'),
  (5, 'Cultivo mixto de encéfalo. Las células verdes son pequeñas, de cuerpo compacto, y están entre prolongaciones rojas muy largas. ¿Qué son las verdes?', 'Microglía', 'microglia|microglias',
      'Es la glía más pequeña.',
      'Marcadas con coronina 1a, una proteína de la actina que la microglía usa para moverse y fagocitar.', 3, NULL, NULL, NULL, '{"img": "img/glia-if/microglia-neuronas.jpg", "pie": "Coronina 1a (verde) · α-internexina (rojo). GerryShaw / EnCor, CC BY-SA 3.0, Wikimedia Commons"}'),
  (5, 'En la misma imagen, las prolongaciones rojas son larguísimas y forman una red. ¿De qué células son?', 'Neurona', 'neuronas',
      'No todo lo que se marca es glía: ¿qué célula tiene prolongaciones tan largas?',
      'Están marcadas con α-internexina, un neurofilamento: el filamento intermedio de las neuronas (el de los astrocitos es GFAP).', 4, NULL, NULL, NULL, '{"img": "img/glia-if/microglia-neuronas.jpg", "pie": "Coronina 1a (verde) · α-internexina (rojo). GerryShaw / EnCor, CC BY-SA 3.0, Wikimedia Commons"}'),
  (5, 'Encéfalo de ratón. La célula verde tiene pocas prolongaciones que corren paralelas, cada una hacia una fibra distinta. ¿Qué célula es?', 'Oligodendrocito', 'oligodendrocitos|oligodendroglia|oligo',
      'Pocas ramas, muchos axones, dentro del SNC.',
      'El anticuerpo Rip marca oligodendrocitos y su mielina: cada prolongación forma un internodo en un axón distinto.', 5, NULL, NULL, NULL, '{"img": "img/glia-if/oligodendrocito-rip.jpg", "pie": "Rip (verde) · núcleos Hoechst (azul). O. Tsupykov, CC BY-SA 4.0, Wikimedia Commons"}'),
  (5, 'Nervio ciático de rata. Lo rojo envuelve, uno por uno, a los axones del nervio. ¿Qué célula es?', 'Célula de Schwann', 'schwann|celulas de schwann',
      'Estás en el SNP, a lo largo de los axones.',
      'S100 (rojo) marca el citoplasma de las células de Schwann; MBP (verde) marca la mielina que forman.', 6, NULL, NULL, NULL, '{"img": "img/glia-if/schwann-mbp-s100.jpg", "pie": "MBP (verde) · S100 (rojo) · núcleos (celeste). V. Ustymenko, CC BY 4.0, Wikimedia Commons"}'),
  (5, 'Ganglio de la raíz dorsal humano (panel A, normal). Una envoltura café, delgada, rodea a cada soma neuronal. ¿Qué glía forma esa cápsula?', 'Célula satélite', 'satelite|satelites',
      'Es la glía de los ganglios, alrededor de los somas.',
      'La laminina marca la lámina basal de las células satélite. En B (ataxia de Friedreich) la cápsula se engruesa en capas.', 7, NULL, NULL, NULL, '{"img": "img/glia-if/satelite-laminina.jpg", "pie": "Laminina, inmunohistoquímica (café). A: normal; B: ataxia de Friedreich. Koeppen et al. en Hanani, CC BY 4.0, Wikimedia Commons"}');

-- Esquemas de glía (tarea B, Kaira Santos): img/glia-snc.jpg y img/glia-snp.jpg (desde la sesión 08, Conoce la glía usa img/glia-snc-tejido.jpg e img/glia-snp-v2.jpg con zonas en el recurso «tareas»).

-- Actividad 13: LA GLÍA EN ACCIÓN (práctico 2) · FUNCIÓN. I unidad neurovascular y sinapsis tripartita («circuito» con etiquetas,
-- vb 1536×1024, y dos recorridos «vias» que se tocan en orden: glucosa y glutamato); II ¿qué cruza la barrera? (práctica «elegir»,
-- practica_niveles numero 2); III mielina y conducción («circuito» con etiquetas); IV rompecabezas de la lesión con piezas mezcladas y
-- sin nombre («barajar», «anonimas»); V glía que cambia: estados funcionales (práctica «elegir», numero 5)
INSERT OR IGNORE INTO actividades (id, topic_id, slug, titulo, descripcion, tipo, activo, objetivo, mecanica, fuente) VALUES
  (13, 7, 'glia-accion', 'La glía en acción',
       'Lo que la glía hace y cómo responde. Nivel I: el astrocito entre el vaso y la sinapsis. Nivel II: qué cruza la barrera hematoencefálica. Nivel III: la mielina y la conducción. Nivel IV: qué pasa tras cortar un axón en el SNP y en el SNC. Nivel V: los estados de la glía en la lesión, el desarrollo y la enfermedad.',
       'lamina', 1, 'Explicar las funciones de la glía (barrera, sinapsis tripartita, metabolismo, conducción saltatoria) y su respuesta a la lesión, la regeneración y la enfermedad.', 'Etiquetar esquemas y trazar recorridos; clasificar sustancias según la barrera; ordenar piezas mezcladas de la lesión; reconocer estados de la glía en casos e imágenes reales.', 'Clase Células del sistema nervioso II y Neurogénesis y neuroplasticidad III 2026 · esquemas de Fernanda López');
INSERT OR IGNORE INTO actividad_recursos (actividad_id, tipo, url, caption, orden) VALUES
  (13, 'tareas', '{"laminas": {}, "niveles": [{"n": 1, "tipo": "circuito", "titulo": "Unidad neurovascular y sinapsis tripartita", "fondo": "img/glia-accion/neurovascular.jpg", "etiquetas": true, "vb": [1536, 1024], "subtitulo": "El astrocito entre el vaso y la sinapsis", "instrucciones": "Primero etiqueta el esquema: elige cada nombre y tócalo. Después <strong>sigue el recorrido</strong> de la glucosa y del glutamato tocando las etiquetas en orden (verás el camino animado). Al final, responde. <strong>Verde</strong>: correcto. <strong>Rojo</strong>: por repasar. <strong>Naranjo</strong>: lo que estás haciendo.", "circuitos": [{"clave": "nv", "titulo": "El astrocito en acción", "ayuda": "Elige un nombre y toca su lugar en el esquema (vale cualquier punto de esa estructura).", "piezas": [{"clave": "luz", "nombre": "Sangre (luz del capilar)", "zona": {"e": [[18.5, 47, 8, 11]]}, "punto": [17, 52], "pista": "Es el interior del vaso, donde está el glóbulo rojo.", "exp": "Trae O₂ y glucosa desde el corazón."}, {"clave": "endotelio", "nombre": "Célula endotelial", "zona": {"e": [[19, 47, 12.5, 17.5]], "no": {"e": [[19, 47, 8.3, 11.3]]}}, "punto": [27.5, 43.5], "pista": "Son las células aplanadas, con núcleo violeta, que forman la pared del capilar por dentro.", "exp": "Forma la pared del capilar; en el SNC no tiene poros."}, {"clave": "union", "nombre": "Unión estrecha", "zona": {"e": [[20, 32, 2.2, 3], [29.4, 52.4, 2.2, 3], [6.5, 42, 2.2, 3], [12.5, 62.5, 2.2, 3]]}, "punto": [12.5, 62.5], "pista": "Es el pequeño «broche» oscuro entre dos células endoteliales vecinas.", "exp": "Sella el espacio entre células endoteliales: es el sello de la barrera hematoencefálica."}, {"clave": "pericito", "nombre": "Pericito", "zona": {"e": [[25, 28, 6, 4]]}, "punto": [25, 28], "pista": "Es la célula amarilla que abraza el capilar por fuera del endotelio.", "exp": "Célula contráctil que abraza el capilar y ayuda a mantener la barrera."}, {"clave": "pie", "nombre": "Pie astrocitario", "zona": {"e": [[19, 47, 17, 23.5]], "no": {"e": [[19, 47, 13.5, 19]]}}, "punto": [4, 40], "pista": "Es la capa rosada más externa que cubre todo el contorno del capilar.", "exp": "Extremo del astrocito que cubre el capilar."}, {"clave": "astro", "nombre": "Astrocito", "zona": {"e": [[52.5, 46, 6, 8]]}, "punto": [52.5, 46], "pista": "Es el soma rosado del centro, de donde salen todas las ramas.", "exp": "Una sola célula conecta el vaso con la sinapsis."}, {"clave": "terminal", "nombre": "Terminal presináptico", "zona": {"e": [[84, 40, 7, 9]]}, "punto": [84, 33], "pista": "Es el extremo violeta con vesículas, arriba a la derecha.", "exp": "Extremo del axón con vesículas de glutamato."}, {"clave": "hendidura", "nombre": "Hendidura sináptica", "zona": {"e": [[86, 53, 6.5, 2.2]]}, "punto": [86, 53.5], "pista": "Es el espacio angosto entre el terminal y la espina.", "exp": "Espacio de unos 20 nm por donde difunde el neurotransmisor."}, {"clave": "espina", "nombre": "Espina dendrítica", "zona": {"e": [[86, 61, 6, 6]]}, "punto": [86, 61], "pista": "Es la protrusión violeta clara bajo la hendidura.", "exp": "Recibe la sinapsis y tiene los receptores de glutamato."}, {"clave": "peri", "nombre": "Prolongación perisináptica", "zona": {"e": [[74.5, 40, 3, 9], [95, 42, 2.6, 14], [84, 19, 4.5, 5]]}, "punto": [74.5, 47], "pista": "Es la rama rosada del astrocito que envuelve la sinapsis por los lados.", "exp": "La tercera parte de la sinapsis tripartita."}], "vias": [{"titulo": "De la sangre a la neurona", "orden": ["luz", "endotelio", "pie", "astro", "terminal"], "ayuda": "Toca las <strong>5 etiquetas</strong> en el orden en que la <strong>glucosa</strong> viaja de la sangre a la neurona.", "ruta": "M284 481 L430 461 L538 451 Q680 440 806 471 Q950 470 1044 451 L1137 410 L1290 410", "exp": "La glucosa cruza el endotelio por transportadores, el pie astrocitario la capta y el astrocito la convierte en lactato (o la guarda como glucógeno). El lactato es el combustible extra de la neurona activa.", "pista": "Empieza en la sangre y termina en la neurona. ¿Qué capa hay que cruzar primero al salir del vaso?"}, {"titulo": "El ciclo del glutamato", "orden": ["terminal", "hendidura", "peri", "astro"], "ayuda": "Ahora sigue al <strong>glutamato</strong>: toca las <strong>4 etiquetas</strong> desde que se libera hasta que el astrocito lo procesa.", "ruta": "M1290 410 L1321 543 Q1220 530 1144 470 Q980 470 806 471", "exp": "El terminal libera glutamato a la hendidura; la prolongación perisináptica lo recapta en milisegundos y el astrocito lo convierte en glutamina, que devuelve a la neurona para fabricar más glutamato.", "pista": "Empieza donde se guarda el glutamato. ¿Quién lo saca de la hendidura?"}], "preguntas": [{"p": "La barrera hematoencefálica impide el paso de la mayoría de las sustancias. ¿Qué forma el sello?", "ops": ["Las uniones estrechas entre células endoteliales; el astrocito y el pericito la inducen y mantienen", "Los pies astrocitarios, pegados unos a otros sin dejar espacios", "La mielina que envuelve a cada capilar del encéfalo", "Los glóbulos rojos, que tapan el capilar cuando llega una toxina"], "ok": 0, "pista": "Busca en el esquema el «broche» entre dos células del capilar.", "exp": "La barrera es una propiedad del endotelio: sus uniones estrechas sellan el paso entre células. Los pies astrocitarios y los pericitos inducen y mantienen ese sello."}, {"p": "Los astrocitos vecinos se unen entre sí por uniones comunicantes (gap). ¿Para qué?", "ops": ["Forman una red que reparte K+, glutamato y metabolitos entre muchos astrocitos", "Transmiten potenciales de acción de un astrocito a otro, como las neuronas", "Forman la mielina de los axones que pasan entre ellos", "Se fusionan en una sola célula gigante con muchos núcleos"], "ok": 0, "pista": "La glía no conduce potenciales de acción. ¿Qué gana si comparte su citoplasma con las vecinas?", "exp": "Acoplados forman un sincicio: el K+ y el glutamato que capta un astrocito se reparten por la red, así ninguna zona se satura."}, {"p": "Durante una actividad intensa, ¿qué le aporta el astrocito a la neurona?", "ops": ["Lactato, a partir de glucosa de la sangre o de su glucógeno", "Mielina nueva, para que conduzca más rápido", "Neurotransmisor ya listo, para que no tenga que fabricarlo", "Oxígeno, que guarda dentro de sus pies perivasculares"], "ok": 0, "pista": "Recuerda el primer recorrido que trazaste.", "exp": "El astrocito guarda glucógeno y entrega lactato a la neurona cuando la demanda sube (lanzadera astrocito-neurona). Además, la actividad aumenta el flujo de sangre local."}, {"p": "En un ACV falta oxígeno y glucosa: el astrocito se queda sin ATP y deja de recaptar glutamato. ¿Qué pasa?", "ops": ["El glutamato se acumula, sobreexcita a las neuronas vecinas, entra Ca²⁺ y mueren", "Falta glutamato en la sinapsis y la neurona deja de recibir señales sin dañarse", "El glutamato se convierte en mielina alrededor de la sinapsis", "La neurona fabrica más glutamina y se protege sola"], "ok": 0, "pista": "Piensa en el segundo recorrido que trazaste: ¿qué pasa si se corta a la mitad?", "exp": "Excitotoxicidad: el glutamato acumulado abre demasiados receptores, entra Ca²⁺ y se activan enzimas que destruyen la neurona. El daño se extiende a la penumbra."}]}]}, {"n": 2, "tipo": "practica", "titulo": "¿Qué cruza la barrera?"}, {"n": 3, "tipo": "circuito", "titulo": "Mielina y conducción", "fondo": "img/glia-accion/mielina.jpg", "etiquetas": true, "subtitulo": "Mielina del SNC (arriba) y del SNP (abajo)", "instrucciones": "Arriba, un oligodendrocito y un astrocito fibroso (SNC); abajo, dos células de Schwann (SNP); en el círculo, un nodo ampliado. Elige cada nombre y tócalo en el esquema; después responde. <strong>Verde</strong>: correcto. <strong>Rojo</strong>: por repasar. <strong>Naranjo</strong>: lo que estás haciendo.", "circuitos": [{"clave": "mielina", "titulo": "Mielina del SNC y del SNP", "ayuda": "Elige un nombre y toca su lugar en el esquema (vale cualquier punto de esa estructura).", "piezas": [{"clave": "axon", "nombre": "Axón", "zona": {"e": [[8, 37.5, 8, 2.2], [76, 62, 12, 2.2], [5, 79.5, 5, 2.2], [93, 79.5, 6, 2.2]]}, "punto": [8, 37.5], "pista": "Es el cilindro violeta que recorre el esquema; míralo donde no tiene mielina encima.", "exp": "Prolongación de la neurona que conduce el impulso."}, {"clave": "oligo", "nombre": "Oligodendrocito", "zona": {"e": [[37.5, 48.5, 4, 5.5]]}, "punto": [37.5, 48.5], "pista": "Es el soma azul entre los dos axones de arriba.", "exp": "Forma la mielina de varios axones del SNC."}, {"clave": "internodo", "nombre": "Internodo (mielina del SNC)", "zona": {"e": [[29, 36, 9, 4], [56, 36.5, 8, 4], [29, 61.5, 9, 4]]}, "punto": [29, 61.5], "pista": "Es un segmento celeste de mielina que sale del oligodendrocito.", "exp": "Tramo de axón envuelto en mielina compacta, entre dos nodos."}, {"clave": "nodo", "nombre": "Nodo de Ranvier", "zona": {"e": [[43, 36.3, 2.2, 2.8], [50, 79.5, 3, 2.6], [20, 61.5, 1.8, 2.6]]}, "punto": [43, 36.3], "pista": "Es el tramo corto de axón desnudo entre dos internodos.", "exp": "Tramo sin mielina: ahí se regenera el impulso."}, {"clave": "fibroso", "nombre": "Astrocito fibroso", "zona": {"e": [[40.5, 13, 5, 7]]}, "punto": [40.5, 13], "pista": "Es la célula rosada de arriba, cuya rama toca un nodo.", "exp": "Astrocito de la sustancia blanca: rodea el nodo."}, {"clave": "schwann", "nombre": "Célula de Schwann", "zona": {"e": [[27, 79, 16.5, 6.5], [73, 79, 16.5, 6.5]]}, "punto": [27, 79], "pista": "Es uno de los segmentos celestes grandes de abajo, con su núcleo dentro.", "exp": "Forma un solo internodo de un solo axón (SNP)."}, {"clave": "neurilema", "nombre": "Neurilema", "zona": {"e": [[27, 79, 19.5, 9.8], [73, 79, 19.5, 9.8]], "no": {"e": [[27, 79, 16.6, 6.6], [73, 79, 16.6, 6.6]]}}, "punto": [27, 71], "pista": "Es la capa lila más externa que envuelve por fuera a cada célula de Schwann.", "exp": "Capa externa de la Schwann, con su lámina basal. El oligodendrocito no la tiene."}, {"clave": "paranodo", "nombre": "Asas paranodales", "zona": {"e": [[76.5, 25, 3, 8], [89, 25, 3, 8]]}, "punto": [76.5, 31], "pista": "En el círculo ampliado, son los bordes enrollados de la mielina pegados al axón, a cada lado del nodo.", "exp": "Sellan la mielina contra el axón a ambos lados del nodo."}, {"clave": "nav", "nombre": "Canales de Na+", "zona": {"e": [[83, 25, 5.5, 6]]}, "punto": [83, 20], "pista": "En el círculo ampliado, son los cilindros amarillos de la membrana del nodo.", "exp": "Canales de sodio dependientes de voltaje, concentrados en el nodo."}], "preguntas": [{"p": "¿Por qué el impulso viaja más rápido en un axón mielinizado?", "ops": ["Se regenera sólo en los nodos y «salta» de uno a otro (conducción saltatoria)", "La mielina conduce la electricidad mejor que el axón", "Hay más canales de Na+ en el internodo que en el nodo", "La mielina empuja los iones a lo largo del axón"], "ok": 0, "pista": "Mira dónde se concentran los canales de Na+ en el círculo ampliado.", "exp": "La mielina aísla el internodo: la corriente avanza por dentro sin perderse y el potencial se regenera sólo en los nodos. Además ahorra ATP, porque entran y se bombean menos iones."}, {"p": "La mielina es 70 % lípidos y 30 % proteínas. ¿Qué proteína predomina en cada sistema?", "ops": ["P0 en el SNP y PLP en el SNC; la MBP está en ambas", "PLP en el SNP y P0 en el SNC; la MBP sólo en el SNP", "MBP sólo en el SNC y P0 sólo en el encéfalo", "Las dos mielinas tienen exactamente las mismas proteínas"], "ok": 0, "pista": "P0 = proteína «cero» de los nervios periféricos.", "exp": "La MBP compacta las capas en ambas. PLP es la mayoritaria del SNC y P0 la del SNP. Por eso una enfermedad puede atacar una mielina y no la otra."}, {"p": "La célula de Schwann tiene neurilema y lámina basal; el oligodendrocito, no. ¿Por qué importa esa diferencia?", "ops": ["Esa envoltura guía al axón si se corta: por eso el SNP puede regenerar", "Esa envoltura hace que el SNP conduzca más rápido que el SNC", "Esa envoltura impide que el SNP tenga nodos de Ranvier", "Esa envoltura sirve para que la Schwann mielinice muchos axones"], "ok": 0, "pista": "Piensa en qué queda en el nervio cuando el axón se rompe.", "exp": "El neurilema y la lámina basal quedan como un tubo guía tras la lesión. Es la clave del pronóstico: presente en el SNP, ausente en el SNC."}, {"p": "Una fibra Aα (12-20 µm, mielinizada) conduce a 70-120 m/s y una fibra C (~1 µm, sin mielina) a 0,5-2 m/s. ¿Qué viaja por las fibras C?", "ops": ["El dolor sordo y la temperatura, que llegan lento", "La orden motora a los músculos, que debe ser rápida", "La propiocepción, que ajusta la postura al instante", "El tacto fino que usamos para leer Braille"], "ok": 0, "pista": "Lo lento y difuso viaja por fibras finas sin mielina.", "exp": "Más diámetro y más mielina = más velocidad. Aα: motora y propiocepción; Aβ: tacto fino; Aδ: dolor agudo; C: dolor sordo, temperatura y funciones viscerales."}]}]}, {"n": 4, "tipo": "rompecabezas", "titulo": "Tras la lesión: SNP frente a SNC", "tablero": "img/glia-accion/lesion-tablero.jpg", "huecos": true, "instrucciones": "Las 8 piezas están <strong>mezcladas y sin nombre</strong>. Mira cada una y decide si es del <strong>SNP</strong> (nervio y músculo) o del <strong>SNC</strong> (médula) y en qué etapa va: toca un hueco y elige su pieza, o arrastra la pieza a su lugar. Al acertar se ve su nombre. <strong>Verde</strong>: correcto. <strong>Rojo</strong>: por repasar. <strong>Naranjo</strong>: lo que estás haciendo.", "piezas": [{"clave": "snp-sano", "nombre": "Nervio sano", "grupo": "snp", "img": "img/glia-accion/piezas/snp-sano.webp", "caja": [1.24, 5.66, 23.44, 36.38], "zona": {"r": [[1.24, 5.66, 23.44, 36.38]]}, "pista": "Esa pieza no va ahí. ¿Tiene músculo (SNP) o red de neuropilo (SNC)? Esta muestra el estado antes de la lesión.", "exp": "Axón mielinizado por células de Schwann que llega a inervar el músculo."}, {"clave": "snp-walleriana", "nombre": "Corte y degeneración walleriana", "grupo": "snp", "img": "img/glia-accion/piezas/snp-walleriana.webp", "caja": [25.91, 5.66, 23.44, 36.38], "zona": {"r": [[25.91, 5.66, 23.44, 36.38]]}, "pista": "Mira el tramo del axón que quedó separado del soma: se está desarmando. Es justo después del corte.", "exp": "Degeneración walleriana: sin contacto con su soma, el tramo distal del axón y su mielina se fragmentan en pocos días."}, {"clave": "snp-tubo", "nombre": "Limpieza y tubo de Schwann", "grupo": "snp", "img": "img/glia-accion/piezas/snp-tubo.webp", "caja": [50.65, 5.66, 23.44, 36.38], "zona": {"r": [[50.65, 5.66, 23.44, 36.38]]}, "pista": "Aparecen células que comen restos y un tubo de células alineadas: es la etapa de limpieza.", "exp": "Los macrófagos y las propias células de Schwann limpian los restos; las Schwann se alinean dentro de su lámina basal y forman un tubo guía (bandas de Büngner)."}, {"clave": "snp-regeneracion", "nombre": "Regeneración y reinervación", "grupo": "snp", "img": "img/glia-accion/piezas/snp-regeneracion.webp", "caja": [75.33, 5.66, 23.44, 36.38], "zona": {"r": [[75.33, 5.66, 23.44, 36.38]]}, "pista": "El axón llega otra vez al músculo, pero con internodos más cortos: es el final.", "exp": "El axón crece ~1 mm al día por dentro del tubo, reinerva el músculo y se remieliniza, con internodos más cortos que antes."}, {"clave": "snc-sano", "nombre": "Axón sano en la médula", "grupo": "snc", "img": "img/glia-accion/piezas/snc-sano.webp", "caja": [1.24, 49.72, 23.44, 47.05], "zona": {"r": [[1.24, 49.72, 23.44, 47.05]]}, "pista": "Hay un oligodendrocito y neuropilo: es SNC, antes de la lesión.", "exp": "Axón del SNC mielinizado por un oligodendrocito, que también mieliniza otros axones."}, {"clave": "snc-corte", "nombre": "Corte sin limpieza", "grupo": "snc", "img": "img/glia-accion/piezas/snc-corte.webp", "caja": [25.91, 49.72, 23.44, 47.05], "zona": {"r": [[25.91, 49.72, 23.44, 47.05]]}, "pista": "Es SNC: el axón está cortado y los restos siguen ahí, sin nadie que limpie.", "exp": "En el SNC la limpieza es lenta: los restos de mielina persisten semanas a meses y tienen proteínas que inhiben el crecimiento del axón."}, {"clave": "snc-reactiva", "nombre": "Glía reactiva", "grupo": "snc", "img": "img/glia-accion/piezas/snc-reactiva.webp", "caja": [50.65, 49.72, 23.44, 47.05], "zona": {"r": [[50.65, 49.72, 23.44, 47.05]]}, "pista": "Es SNC: llegan células de defensa y astrocitos más grandes.", "exp": "La microglía se activa (se redondea y fagocita) y los astrocitos se vuelven reactivos: más grandes y con más GFAP."}, {"clave": "snc-cicatriz", "nombre": "Cicatriz glial", "grupo": "snc", "img": "img/glia-accion/piezas/snc-cicatriz.webp", "caja": [75.33, 49.72, 23.44, 47.05], "zona": {"r": [[75.33, 49.72, 23.44, 47.05]]}, "pista": "Es SNC: una barrera densa de astrocitos frente al axón detenido. Es el final.", "exp": "Cicatriz glial: aísla la lesión y protege el tejido sano, pero el axón queda detenido en un bulbo de retracción frente a ella."}], "preguntas": [{"p": "¿Por qué el axón periférico puede volver a crecer y el de la médula casi no?", "ops": ["La Schwann limpia rápido y forma un tubo guía; en el SNC quedan restos inhibidores y una cicatriz", "Las neuronas del SNP se dividen y reemplazan a las que perdieron el axón", "En el SNC no hay glía que limpie, así que el axón crece sin ninguna guía", "El axón periférico es más corto y no necesita una guía para volver a crecer"], "ok": 0, "pista": "Compara la fila de arriba con la de abajo en el tercer y cuarto paso.", "exp": "En el SNP los macrófagos y la Schwann limpian en días y la Schwann guía al axón (~1 mm/día). En el SNC la mielina del oligodendrocito tiene inhibidores (Nogo, MAG), se limpia lento y la cicatriz glial frena al axón."}, {"p": "Un nervio aplastado (su vaina de tejido conectivo queda intacta) se recupera mejor que uno cortado. ¿Por qué?", "ops": ["La vaina intacta guía a cada axón por su mismo tubo hasta su blanco", "En el aplastamiento no hay degeneración walleriana", "El aplastamiento hace que las neuronas se dividan", "En el corte, la microglía forma una cicatriz dentro del nervio"], "ok": 0, "pista": "Piensa en qué pasa con los tubos si hay que unir dos extremos separados.", "exp": "En el corte hay que reconectar los extremos y muchos axones se desordenan al cruzar la brecha. En el aplastamiento cada axón vuelve a crecer por su propio tubo."}, {"p": "Si a un axón del SNC (nervio óptico) se le injerta un trozo de nervio periférico, el axón crece dentro del injerto. ¿Qué demuestra?", "ops": ["Que la neurona del SNC sí puede crecer: lo que la frena es su entorno", "Que las neuronas del SNC se transforman en neuronas del SNP", "Que el injerto aporta neuronas nuevas que reemplazan a las dañadas", "Que el nervio óptico es parte del SNP y no del SNC"], "ok": 0, "pista": "El injerto trae células de Schwann.", "exp": "Es el experimento de Aguayo (años 80): con células de Schwann alrededor, axones del SNC crecen centímetros. El problema del SNC es el ambiente, no la neurona."}, {"p": "La cicatriz glial, ¿es sólo dañina?", "ops": ["No: aísla la lesión y protege el tejido sano, aunque frene al axón", "Sí: sólo impide el crecimiento y no cumple ninguna función de defensa", "No: está formada por neuronas nuevas que reemplazan a las perdidas", "Sí: es mielina acumulada que impide que llegue sangre a la lesión"], "ok": 0, "pista": "Piensa en qué pasaría con el tejido vecino si la lesión no se aislara.", "exp": "La cicatriz de astrocitos reactivos contiene la inflamación y vuelve a sellar la barrera, pero también es una barrera para el axón: por eso en el SNC la recuperación depende de la plasticidad."}], "textos": {"paso": "Arma las dos secuencias", "fijo": " Arriba va el SNP y abajo el SNC.", "armado": "Tus dos secuencias ordenadas", "img": "Tras la lesión: SNP frente a SNC", "pie": ".", "guia": "Qué pasa tras cortar un axón en el SNP y en el SNC"}, "barajar": true, "anonimas": true}, {"n": 5, "tipo": "practica", "titulo": "Glía que cambia"}]}', NULL, 1);
INSERT OR IGNORE INTO practica_niveles (id, actividad_id, numero, titulo, instrucciones, tipo, activo) VALUES
  (8, 13, 2, '¿Qué cruza la barrera?', 'Lee cada sustancia y toca la tarjeta: ¿<strong>pasa libremente</strong>, <strong>pasa con transportador</strong> o <strong>no pasa</strong> la barrera hematoencefálica? Cada acierto se anota en el cuadro. <strong>Rojo</strong>: esa no era; lee la pista y prueba con otra.', 'elegir', 1),
  (6, 13, 5, 'Glía que cambia', 'La misma célula cambia según lo que pasa a su alrededor. Lee el caso (o mira la imagen) y toca la tarjeta del <strong>estado</strong> en que está la glía. <strong>Rojo</strong>: esa no era; lee la pista y prueba con otra.', 'elegir', 1);
INSERT OR IGNORE INTO practica_items (nivel_id, enunciado, respuesta, sinonimos, pista, explicacion, orden, fila, celda, nota, datos) VALUES
  (8, 'Oxígeno (O₂) que trae la sangre.', 'Pasa libremente', 'libre|pasa libre|difunde',
      'Es un gas pequeño.',
      'Los gases difunden a través de las membranas del endotelio.', 1, 'Ejemplos', 'O₂', NULL, NULL),
  (8, 'Dióxido de carbono (CO₂) que sale del tejido nervioso.', 'Pasa libremente', 'libre|pasa libre|difunde',
      'Es un gas pequeño.',
      'Difunde en ambos sentidos, de donde hay más a donde hay menos.', 2, 'Ejemplos', 'CO₂', NULL, NULL),
  (8, 'Alcohol y anestésicos generales: moléculas pequeñas y liposolubles.', 'Pasa libremente', 'libre|pasa libre|difunde',
      'Lo que se disuelve en lípidos atraviesa la membrana.',
      'Por eso actúan tan rápido sobre el encéfalo.', 3, 'Ejemplos', 'Alcohol, anestésicos', NULL, NULL),
  (8, 'Glucosa, el combustible principal del encéfalo.', 'Pasa con transportador', 'transportador|con transportador',
      'Es hidrosoluble, pero el encéfalo no puede vivir sin ella.',
      'Cruza por el transportador GLUT1 del endotelio.', 4, 'Ejemplos', 'Glucosa', NULL, NULL),
  (8, 'Aminoácidos que la neurona usa para fabricar neurotransmisores.', 'Pasa con transportador', 'transportador|con transportador',
      'Son necesarios pero no liposolubles.',
      'Tienen transportadores específicos en el endotelio.', 5, 'Ejemplos', 'Aminoácidos', NULL, NULL),
  (8, 'L-dopa, el fármaco que se usa en el Parkinson.', 'Pasa con transportador', 'transportador|con transportador',
      'Se parece a un aminoácido.',
      'Usa el transportador de aminoácidos; dentro del encéfalo se transforma en dopamina.', 6, 'Ejemplos', 'L-dopa', NULL, NULL),
  (8, 'Dopamina en pastilla, la molécula que falta en el Parkinson.', 'No pasa', 'no|no pasa|bloqueada',
      'Si pasara, ¿para qué se usaría la L-dopa?',
      'No tiene transportador: por eso se da su precursor, la L-dopa.', 7, 'Ejemplos', 'Dopamina', NULL, NULL),
  (8, 'Albúmina y anticuerpos del plasma.', 'No pasa', 'no|no pasa|bloqueada',
      'Son proteínas grandes.',
      'Las proteínas plasmáticas quedan fuera: el LCR casi no tiene proteínas.', 8, 'Ejemplos', 'Proteínas del plasma', NULL, NULL),
  (8, 'Bacterias que circulan por la sangre.', 'No pasa', 'no|no pasa|bloqueada',
      'Son mucho más grandes que una molécula.',
      'Si la barrera se daña (meningitis), pueden entrar.', 9, 'Ejemplos', 'Bacterias', NULL, NULL),
  (8, 'La mayoría de los fármacos, como muchos antibióticos y quimioterapias.', 'No pasa', 'no|no pasa|bloqueada',
      'Es uno de los grandes desafíos para tratar el encéfalo.',
      'Por eso hay que diseñar fármacos que usen transportadores o se den dentro del LCR.', 10, 'Ejemplos', 'Mayoría de los fármacos', NULL, NULL),
  (8, 'Una toxina de la sangre llega a las neuronas del área postrema (un órgano circunventricular) y provoca vómito.', 'Pasa libremente', 'libre|pasa libre|difunde',
      'En los órganos circunventriculares los capilares sí tienen poros.',
      'Son zonas sin barrera: así el encéfalo «muestrea» la sangre.', 11, 'Ejemplos', 'Órganos circunventriculares', NULL, NULL),
  (6, 'Tejido sano: sus ramas se mueven todo el tiempo y escanean el tejido en pocas horas. Cada célula ocupa su propio territorio.', 'Microglía vigilante', 'vigilante|microglia vigilante|m0|reposo',
      '«En reposo» es un nombre engañoso: nunca está quieta.',
      'Es el estado basal (M0): monitorea el ambiente y detecta señales de peligro.', 1, NULL, NULL, NULL, '{"img": "img/glia-if/microglia-iba1.jpg", "pie": "Iba1 (rojo) · ADN (azul). J. Wegiel, CC BY 4.0, Wikimedia Commons"}'),
  (6, 'Detecta restos de un patógeno: se redondea, fagocita y libera TNF-α e IL-1β.', 'Microglía proinflamatoria (M1)', 'm1|proinflamatoria|microglia m1',
      'Fagocitosis más citoquinas inflamatorias.',
      'M1: defensa y limpieza. Si se cronifica, daña neuronas, sinapsis y mielina.', 2, NULL, NULL, NULL, NULL),
  (6, 'En un ambiente con IL-4 e IL-10 secreta BDNF y ayuda a resolver la inflamación.', 'Microglía reparadora (M2)', 'm2|reparadora|antiinflamatoria|microglia m2',
      'Factores neurotróficos y resolución.',
      'M2: reparación del tejido, formación de vasos y apoyo a las neuronas.', 3, NULL, NULL, NULL, NULL),
  (6, 'En el Alzheimer, la microglía queda activada por años y contribuye a la poda excesiva de sinapsis y a la excitotoxicidad.', 'Microglía proinflamatoria (M1)', 'm1|proinflamatoria|microglia m1',
      'Es el lado dañino de la activación.',
      'La neuroinflamación crónica es un motor del deterioro en enfermedades neurodegenerativas.', 4, NULL, NULL, NULL, NULL),
  (6, 'Corteza de un modelo de Alzheimer: astrocitos GFAP+ (rojo) rodean las placas (verde), aumentan el complemento C3 y dañan sinapsis.', 'Astrocito reactivo neurotóxico (A1)', 'a1|neurotoxico|astrocito a1',
      'Los induce la microglía activada (IL-1α, TNF, C1q).',
      'A1: pierden sus funciones de apoyo y se vuelven tóxicos para neuronas y oligodendrocitos.', 5, NULL, NULL, NULL, '{"img": "img/glia-if/astrocitos-placas.jpg", "pie": "GFAP (rojo) · placas de amiloide (verde). Pics56, CC BY-SA 4.0, Wikimedia Commons"}'),
  (6, 'Tras una isquemia aparecen astrocitos que liberan factores que protegen a las neuronas y reparan sinapsis.', 'Astrocito reactivo protector (A2)', 'a2|protector|neuroprotector|astrocito a2',
      'Los induce la isquemia.',
      'A2: neuroprotectores. Hoy A1 y A2 se entienden como extremos de un continuo.', 6, NULL, NULL, NULL, NULL),
  (6, 'Junto a la lesión, astrocitos hipertróficos que proliferan y aumentan GFAP y proteoglicanos (CSPG).', 'Astrocito de la cicatriz', 'cicatriz|astrocito de la cicatriz|formador de cicatriz',
      'Es la barrera que viste en el rompecabezas.',
      'Aísla la lesión y protege el tejido sano, pero los CSPG frenan el crecimiento del axón.', 7, NULL, NULL, NULL, NULL),
  (6, 'En el embrión, sus prolongaciones van del ventrículo a la superficie y sirven de riel a las neuronas que migran.', 'Glía radial', 'radial|glia radial',
      'Es glía del desarrollo.',
      'Es precursora de neuronas y astrocitos; al terminar la migración se transforma en astrocito. Si falla la migración: displasias corticales y epilepsia.', 8, NULL, NULL, NULL, NULL),
  (6, 'Las células verdes (NG2), pequeñas y ramificadas, persisten en el adulto y pueden convertirse en células que vuelven a formar mielina.', 'Precursor de oligodendrocito (NG2)', 'ng2|opc|precursor|precursor de oligodendrocito',
      'Mira el color verde y piensa en quién mieliniza el SNC.',
      'Son precursores de oligodendrocitos (OPC). En la esclerosis múltiple migran a la placa y remielinizan, aunque con mielina más delgada.', 9, NULL, NULL, NULL, '{"img": "img/glia-if/ng2-gfap.jpg", "pie": "NG2 (verde) · GFAP (rojo) · núcleos (azul). O. Tsupykov, CC BY-SA 4.0, Wikimedia Commons"}');

-- Actividad 12: QUIZ de cierre Células nerviosas II (la glía)
INSERT OR IGNORE INTO actividades (id, topic_id, slug, titulo, descripcion, tipo, activo) VALUES
  (12, 7, 'quiz-celulas-nerviosas-2', 'Quiz: Células nerviosas II (la glía)',
       'Cierre del práctico: preguntas de un pool común y casos de tu carrera (TO o Fono); algunas se responden con tarjetas. Una sola oportunidad por pregunta; cada respuesta muestra una explicación.', 'quiz', 1);
INSERT OR IGNORE INTO quices (actividad_id, titulo, datos_json, activo) VALUES
  (12, 'Células nerviosas II', '[{"id": "c01", "carrera": "comun", "pregunta": "En el encéfalo humano, ¿cuál es la proporción aproximada entre glía y neuronas?", "opciones": ["Cerca de 1 glía por cada neurona", "10 glías por cada neurona", "1 glía por cada 10 neuronas", "50 glías por cada neurona"], "correcta": 0, "feedback": "Los recuentos actuales dan una proporción cercana a 1:1 en el encéfalo humano; la idea de «10 veces más glía» es un mito."}, {"id": "c02", "carrera": "comun", "pregunta": "¿Qué célula glial no nace del tejido nervioso, sino de precursores inmunes (mesodermo)?", "opciones": ["Astrocito", "Oligodendrocito", "Microglía", "Célula ependimaria"], "correcta": 2, "feedback": "La microglía viene de los mismos precursores que los macrófagos y entra al SNC durante el desarrollo.", "tarjetas": true}, {"id": "c04", "carrera": "comun", "pregunta": "Durante el desarrollo se forman más sinapsis de las necesarias. ¿Qué célula elimina las que no se usan (poda sináptica)?", "opciones": ["Astrocito", "Oligodendrocito", "Microglía", "Célula ependimaria"], "correcta": 2, "feedback": "La microglía poda las sinapsis poco activas; así se refinan los circuitos. Una poda excesiva se asocia a enfermedades del neurodesarrollo y neurodegenerativas.", "tarjetas": true}, {"id": "c05", "carrera": "comun", "pregunta": "Un axón del nervio ciático está mielinizado por muchas células, una detrás de otra. ¿Cuáles son?", "opciones": ["Oligodendrocito", "Célula de Schwann", "Célula satélite", "Astrocito"], "correcta": 1, "feedback": "En el SNP cada célula de Schwann forma un solo internodo: un axón largo necesita cientos de ellas en fila.", "tarjetas": true}, {"id": "c03", "carrera": "comun", "pregunta": "Quieres ver en un corte a los astrocitos completos, con todas sus prolongaciones. ¿Qué marcador usas?", "opciones": ["GFAP", "Iba1", "MBP", "Laminina"], "correcta": 0, "feedback": "GFAP es el filamento intermedio de los astrocitos. Iba1 marca microglía, MBP la mielina y la laminina la lámina basal (por ejemplo, de las células satélite)."}, {"id": "c08", "carrera": "comun", "pregunta": "La barrera hematoencefálica impide que la mayoría de los fármacos llegue al encéfalo. ¿Qué forma el sello que los detiene?", "opciones": ["Uniones estrechas entre las células del endotelio capilar", "Pies de astrocitos pegados unos a otros, sin espacios", "Una capa de mielina que envuelve a cada capilar cerebral", "Células ependimarias que tapizan los vasos sanguíneos"], "correcta": 0, "feedback": "La barrera es una propiedad del endotelio: sus uniones estrechas sellan el paso entre células. Los pies astrocitarios la inducen y la mantienen, pero no son el sello."}, {"id": "c11", "carrera": "comun", "pregunta": "En el Parkinson falta dopamina, pero se trata con L-dopa y no con dopamina. ¿Por qué?", "opciones": ["La L-dopa cruza la barrera por un transportador y la dopamina no puede cruzarla", "La dopamina es tóxica para el hígado y la L-dopa no", "La L-dopa forma mielina nueva en los axones dopaminérgicos", "La dopamina cruza la barrera, pero la microglía la destruye"], "correcta": 0, "feedback": "La L-dopa usa el transportador de aminoácidos del endotelio; dentro del encéfalo se convierte en dopamina."}, {"id": "c09", "carrera": "comun", "pregunta": "Tras cortarse, un axón del nervio mediano puede volver a crecer, pero uno de la médula espinal casi no. ¿Qué explica la diferencia?", "opciones": ["En el SNP la célula de Schwann forma un tubo guía; en el SNC hay cicatriz glial", "En el SNP el axón es más grueso; en el SNC los axones son demasiado delgados", "En el SNP no hay glía que estorbe; en el SNC los oligodendrocitos se dividen", "En el SNP la neurona se divide; en el SNC las neuronas maduras no se dividen"], "correcta": 0, "feedback": "La célula de Schwann y su lámina basal guían al axón (~1 mm/día). En el SNC, los astrocitos reactivos forman la cicatriz glial y la mielina del oligodendrocito tiene inhibidores del crecimiento."}, {"id": "c12", "carrera": "comun", "pregunta": "Un estímulo doloroso produce primero un dolor agudo y, un segundo después, uno sordo y quemante. ¿Qué explica la demora del segundo?", "opciones": ["Viaja por fibras C, delgadas y sin mielina, que conducen lento", "Viaja por fibras Aα, gruesas y mielinizadas, que conducen lento", "Tiene que pasar primero por el oligodendrocito de la piel", "Espera a que la microglía libere citoquinas en la médula"], "correcta": 0, "feedback": "Dolor agudo: fibras Aδ (finas, con poca mielina). Dolor sordo: fibras C, sin mielina, ~0,5-2 m/s, envueltas por células de Schwann no mielinizantes."}, {"id": "k1", "carrera": "comun", "pregunta": "Una persona con diabetes pierde el reflejo aquíleo y la sensibilidad en los pies; el estudio muestra conducción lenta en los nervios de las piernas. ¿Qué glía está dañada?", "opciones": ["Oligodendrocito", "Célula de Schwann", "Célula satélite", "Astrocito"], "correcta": 1, "feedback": "La conducción lenta en nervios periféricos indica daño de la mielina del SNP, que forman las células de Schwann.", "tarjetas": true}, {"id": "k2", "carrera": "comun", "pregunta": "En un brote de esclerosis múltiple, la resonancia muestra placas en la sustancia blanca del encéfalo. ¿Qué célula es el blanco del daño?", "opciones": ["Astrocito", "Oligodendrocito", "Microglía", "Célula ependimaria"], "correcta": 1, "feedback": "La esclerosis múltiple destruye la mielina del SNC, que forman los oligodendrocitos.", "tarjetas": true}, {"id": "k4", "carrera": "comun", "pregunta": "Después de un herpes zóster, una persona queda con dolor quemante sin lesión visible en la piel. ¿Qué glía del ganglio sensitivo se asocia a ese dolor neuropático?", "opciones": ["Oligodendrocito", "Célula de Schwann", "Célula satélite", "Astrocito"], "correcta": 2, "feedback": "El virus queda latente en el ganglio sensitivo. Las células satélite alteradas dejan a la neurona hiperexcitable: dolor neuropático.", "tarjetas": true}, {"id": "t2", "carrera": "terapia-ocupacional", "pregunta": "En la rehabilitación tras un ACV, la práctica repetida favorece la formación de sinapsis nuevas y la eliminación de las que no se usan. ¿Qué glía participa?", "opciones": ["Astrocitos (forman sinapsis) y microglía (poda las que no se usan)", "Oligodendrocitos (forman sinapsis) y ependimarias (podan las que sobran)", "Células de Schwann (forman sinapsis) y satélite (podan las que sobran)", "Microglía (forma sinapsis) y astrocitos (podan las que no se usan)"], "correcta": 0, "feedback": "Los astrocitos favorecen la sinaptogénesis y la plasticidad; la microglía poda sinapsis. Ambas son parte de la base celular de la rehabilitación."}, {"id": "t3", "carrera": "terapia-ocupacional", "pregunta": "En la ELA, astrocitos que recaptan poco glutamato contribuyen a la muerte de las motoneuronas. ¿Cuál es el mecanismo?", "opciones": ["El glutamato se acumula en la sinapsis y sobreexcita a la neurona", "Falta glutamato en la sinapsis y la neurona deja de recibir señales", "Los astrocitos fagocitan a las motoneuronas que tienen poco glutamato", "El glutamato destruye la mielina que rodea al axón de la motoneurona"], "correcta": 0, "feedback": "Excitotoxicidad: el exceso de glutamato abre demasiados canales, entra Ca2+ en exceso y la neurona muere."}, {"id": "t5", "carrera": "terapia-ocupacional", "pregunta": "Una persona se corta el nervio mediano en la muñeca, a unos 10 cm de los músculos de la mano que inerva. Si el axón crece ~1 mm al día, ¿cuándo esperas los primeros signos de reinervación?", "opciones": ["En unos 3 meses", "En unos 3 días", "En unos 3 años", "Nunca: el SNP no regenera"], "correcta": 0, "feedback": "100 mm ÷ 1 mm/día ≈ 100 días. Mientras tanto se mantiene la movilidad, se protege la piel sin sensibilidad y se reeduca la sensibilidad."}, {"id": "t6", "carrera": "terapia-ocupacional", "pregunta": "Una persona con esclerosis múltiple refiere fatiga y torpeza que empeoran al final del día y con calor. ¿Qué explica estos síntomas?", "opciones": ["Sus axones sin mielina conducen lento o bloquean el impulso", "Sus motoneuronas mueren por falta de glutamato en la sinapsis", "Sus células de Schwann forman cicatriz en los nervios de la mano", "Su microglía forma más mielina de la que los axones necesitan"], "correcta": 0, "feedback": "En el SNC desmielinizado la conducción saltatoria falla: la señal se enlentece o se bloquea. El calor empeora aún más la conducción en esas zonas."}, {"id": "f2", "carrera": "fonoaudiologia", "pregunta": "En la esclerosis múltiple puede aparecer habla lenta y entrecortada (disartria) por placas en el tronco y el cerebelo. ¿Por qué se altera la señal?", "opciones": ["Se pierde la mielina de los oligodendrocitos y la señal se enlentece", "Se pierde la mielina de las células de Schwann: el impulso se acelera", "Mueren las motoneuronas de la lengua: el músculo se atrofia", "Se bloquean las sinapsis por exceso de LCR en los ventrículos"], "correcta": 0, "feedback": "Las placas desmielinizan axones del SNC: la conducción se enlentece o se bloquea y se pierde la coordinación fina de la articulación."}, {"id": "f3", "carrera": "fonoaudiologia", "pregunta": "Un schwannoma vestibular (neurinoma del acústico) produce hipoacusia de un lado y tinnitus. ¿De qué células nace este tumor?", "opciones": ["Oligodendrocito", "Célula de Schwann", "Célula satélite", "Astrocito"], "correcta": 1, "feedback": "Nace de las células de Schwann del nervio vestibular; al crecer comprime el nervio coclear vecino.", "tarjetas": true}, {"id": "f4", "carrera": "fonoaudiologia", "pregunta": "Cerca del tronco encefálico, la mielina del nervio auditivo deja de formarla la célula de Schwann y pasa a formarla el oligodendrocito. ¿Qué indica ese cambio?", "opciones": ["Que el nervio pasa del SNP al SNC", "Que el nervio pasa de sensitivo a motor", "Que el axón termina y empieza otro", "Que el nervio pierde toda su mielina"], "correcta": 0, "feedback": "La zona de transición marca el límite SNP–SNC. Los schwannomas vestibulares suelen nacer cerca de esa zona."}, {"id": "f5", "carrera": "fonoaudiologia", "pregunta": "Tras una cirugía de tiroides, una persona queda con voz débil por lesión del nervio laríngeo recurrente. ¿Por qué es posible que la voz se recupere?", "opciones": ["Es un nervio del SNP: la célula de Schwann guía el rebrote del axón", "Es un nervio del SNC: el oligodendrocito forma mielina nueva en él", "La laringe forma neuronas nuevas que reemplazan a las que se dañaron", "La microglía del nervio forma una cicatriz que vuelve a conducir"], "correcta": 0, "feedback": "El laríngeo recurrente es una rama del vago (SNP): su axón puede volver a crecer guiado por las células de Schwann. La terapia mantiene la musculatura y acompaña la recuperación."}]', 1);

INSERT OR IGNORE INTO actividad_carrera (actividad_id, carrera_id, descripcion, orden) VALUES
  (12, 2, 'Responde solo/a, sin apuntes. Al terminar revisa el resumen: las preguntas falladas son las que conviene repasar.', 1);
